import { goldLessons } from '../gold.ts';
import type { LessonExpansion } from '../types.ts';
import { expand } from './intermediate-builder.ts';
const result: Record<string, LessonExpansion> = {};
const add = (slug: string, ...args: Parameters<typeof expand> extends [unknown, ...infer R] ? R : never) => {
 const lesson=goldLessons.find(item=>item.id===`usaco-gold-${slug}`);
 if(!lesson) throw new Error(slug);
 result[lesson.id]=expand(lesson,...args);
};

add('divisibility',[
 {title:'Divisores, primos y factorización',body:'Un entero positivo d divide a n si n=d·k para algún entero k, equivalente a n%d=0. Un primo tiene exactamente dos divisores positivos, 1 y él mismo; por eso 1 no es primo. Si n es compuesto, tiene algún divisor a lo sumo raíz de n: si ambos factores fueran mayores, su producto excedería n. Para factorizar, prueba d desde 2 mientras d≤n/d y divide repetidamente cuando corresponda. Cada división extrae una copia de ese primo. Si al terminar queda n>1, ese resto es primo. La comparación con n/d evita desbordar d*d.'},
 {title:'Euclides explicado por divisores comunes',body:'Si a=q·b+r, un número divide a a y b exactamente cuando divide a b y r. En un sentido, r=a−q·b; en el otro, a=q·b+r. Por tanto mcd(a,b)=mcd(b,a%b). Para 84 y 30: 84%30=24, 30%24=6, 24%6=0, luego el mcd es 6. El caso base mcd(a,0)=a corresponde a que todos los divisores de a también dividen cero. El mínimo común múltiplo de positivos cumple mcm(a,b)=(a/mcd(a,b))·b; dividir antes reduce el riesgo de desbordamiento.'},
 {title:'Criba para muchas preguntas',body:'Si necesitas todos los primos hasta N, repetir división de prueba para cada número cuesta demasiado. La criba marca inicialmente a todos como candidatos salvo 0 y 1. Para cada primo p, marca sus múltiplos desde p²: los anteriores ya tenían un factor menor. Con N=20, el 2 elimina 4,6,8,…; el 3 elimina 9,12,15,18; no hace falta procesar 5 porque 5²>20. El tiempo es O(N log log N) y la memoria O(N). Una tabla de menor factor primo permite descomponer después cada número mediante divisiones sucesivas.'},
 {title:'Usar exponentes en una factorización',body:'Si n=p1^e1·p2^e2·…, cada divisor elige independientemente un exponente entre 0 y ei para cada primo. Por ello la cantidad de divisores es (e1+1)(e2+1)… Por ejemplo, 72=2³·3² tiene 4·3=12 divisores. Para mcd entre dos números tomas el mínimo exponente de cada primo; para mcm, el máximo. Estas ideas requieren positivos para usar esta factorización usual. Trabaja con valores absolutos al hablar de mcd de negativos, y evita el mínimo entero de 64 bits si vas a negarlo: su positivo no cabe en el mismo tipo.'},
],{title:'Repartir sin sobrantes',prompt:'Dos cajas contienen 84 y 126 fichas. Quieres crear bolsas con la misma cantidad de fichas, sin mezclar cajas y sin sobrantes. Encuentra la mayor cantidad por bolsa, el número total de bolsas y el mcm de las dos cantidades. Factoriza además 84 y cuenta sus divisores.',hints:['La cantidad por bolsa debe dividir a ambos números.', '84=2²·3·7.'],solution:'mcd(126,84)=mcd(84,42)=42. Cada bolsa contiene 42 fichas: salen 2 de la primera caja y 3 de la segunda, cinco en total. El mcm es (84/42)·126=252. Como 84=2²·3¹·7¹, tiene (2+1)(1+1)(1+1)=12 divisores positivos. La cuenta de divisores no pide enumerar todas las bolsas; responde una pregunta distinta sobre las posibles cantidades que dividen 84.'},{title:'Tamaño común de equipos',prompt:'Lee dos enteros a,b no negativos, no ambos cero. Imprime su máximo común divisor. Límites: 0 ≤ a,b ≤ 1000000000000. Resuelve usando Euclides o gcd de la biblioteca estándar, entendiendo su fundamento.',hints:['Reemplaza (a,b) por (b,a%b) mientras b no sea cero.', 'No calcules a%b cuando b=0.'],solution:'Cada reemplazo conserva exactamente los divisores comunes y reduce el segundo valor hasta cero. En ese momento el primer valor es el máximo divisor común. El tiempo es O(log(max(a,b))) y la memoria O(1). La función gcd de <numeric> implementa este concepto y está disponible en C++17. El caso con un cero responde el otro número.',tests:[{input:'84 126\n',output:'42\n'},{input:'0 17\n',output:'17\n'},{input:'1000000000000 999999999999\n',output:'1\n'}]});

add('modular',[
 {title:'Residuos que se pueden reemplazar',body:'Decir a≡b módulo m significa que m divide a−b. Si a y b son congruentes, reemplazar uno por otro dentro de sumas y productos conserva el residuo. Esta es la razón para reducir después de cada operación: no estamos aproximando el resultado. Para restar residuos normalizados, (a−b+m)%m evita un negativo cuando a y b están entre 0 y m−1. Con operandos arbitrarios primero normaliza cada uno. En C++, −3%7 produce −3; normalizar da 4, que es el representante de 0 a 6.'},
 {title:'La potencia rápida como un invariante',body:'Empieza con respuesta=1, base=a y exponente=e. Si e es impar, transfiere un factor base a respuesta. Después eleva base al cuadrado y divide e entre dos. La identidad base^(2k)=(base²)^k y su versión impar garantizan que respuesta·base^exponente sigue representando a^e. Para 5^6 módulo 13: cuadramos 5 a 12 y e baja a 3; incorporamos 12, cuadramos a 1 y e baja a 1; incorporamos 1 y terminamos en 12. Cada vuelta consume un bit: incluso e=10 elevado a 18 necesita unas 60 vueltas.'},
 {title:'Por qué la división modular no es división usual',body:'De 2·x≡4 módulo 6 no se deduce una única x: sirven 2 y 5. El 2 no tiene inverso porque comparte divisor con 6. En general existe inverso de a módulo m si y solo si mcd(a,m)=1. El algoritmo extendido de Euclides produce x,y con ax+my=mcd(a,m); si vale 1, x normalizado es el inverso. Si m es primo y a no es múltiplo suyo, también sirve a^(m−2). No uses esa potencia para un módulo compuesto sin una justificación distinta.'},
 {title:'Límites del producto y elecciones del módulo',body:'Con m≤1000000007, el producto de dos residuos menores que m cabe en long long, pero puede exceder int. Asegura que la multiplicación ya ocurra en 64 bits; guardar después el resultado en long long no repara un desbordamiento previo. El exponente cero produce 1%m, que es cero si m=1. La potencia 0^0 suele definirse como 1 por el producto vacío en algoritmos combinatorios; el enunciado debe fijar la convención. Nunca elijas un módulo «para que quepa» si el problema pide la respuesta exacta: cambiarías la pregunta.'},
],{title:'Divide solo cuando esté permitido',prompt:'Calcula 4^5 módulo 7 y resuelve 3x≡1 módulo 7. Luego encuentra todas las soluciones x entre 0 y 7 de 2x≡4 módulo 8. Explica por qué el último problema no equivale a multiplicar por un inverso de 2.',hints:['4²≡2 y 4⁴≡4 módulo 7.', 'Prueba la condición mcd(2,8).'],solution:'4^5≡4·4≡2 módulo 7. El inverso de 3 es 5 porque 3·5=15≡1. Para 2x≡4 módulo 8 sirven x=2 y x=6. No hay inverso de 2 porque mcd(2,8)=2; multiplicar por 2 pierde información al identificar residuos diferentes. La existencia de dos soluciones muestra por qué dividir residuos como enteros puede borrar respuestas o producir una conclusión incorrecta.'},{title:'Potencias del marcador',prompt:'Lee a,e,m. Imprime el residuo normalizado de a elevado a e módulo m. Límites: |a| ≤ 1000000000; 0 ≤ e ≤ 1000000000000000000; 1 ≤ m ≤ 1000000007. Usa 0^0=1 para este ejercicio.',hints:['Normaliza a antes de multiplicar.', 'Descompón e en bits, no hagas e multiplicaciones.'],solution:'La potencia rápida conserva respuesta·base^exponente módulo m. Multiplica respuesta por base cuando el bit bajo es uno y eleva base al cuadrado en cada vuelta. Se necesitan O(log(e+1)) operaciones y O(1) memoria. Inicializar respuesta=1%m maneja m=1 de forma consistente. Todos los productos son entre residuos menores que 1000000007 y caben en long long.',tests:[{input:'4 5 7\n',output:'2\n'},{input:'-3 3 7\n',output:'1\n'},{input:'0 0 1\n',output:'0\n'},{input:'2 0 13\n',output:'1\n'}]});

add('combo',[
 {title:'Sumar casos y multiplicar decisiones',body:'Si eliges una camiseta de tres colores y una gorra de cuatro modelos, hay 3·4=12 combinaciones. Multiplicas porque cada elección se combina con todas las de la siguiente. Si puedes entrar por dos puertas de estudiantes o por tres de visitantes, hay 2+3=5 opciones, siempre que los casos sean distintos y completos. Antes de escribir una fórmula describe qué constituye un resultado: una lista ordenada, un conjunto o una distribución. Contar ordenaciones cuando el problema pide conjuntos multiplica indebidamente la respuesta.'},
 {title:'Permutaciones y repeticiones',body:'Ordenar n objetos distintos da n!: hay n opciones para la primera posición, n−1 para la segunda y así sucesivamente. Si entre ellos hay c1 copias de un tipo, c2 de otro, divide por c1!c2!… porque intercambiar copias iguales no produce una secuencia nueva. Las letras de MAMA forman 4!/(2!2!)=6 cadenas distintas. Elegir k objetos ordenados y sin repetición da n!/(n−k)!, mientras elegir un conjunto da además una división por k!. Esas divisiones cuentan cuántas representaciones tiene el mismo objeto final.'},
 {title:'Distribuir objetos y excluir casos',body:'Distribuir r fichas idénticas entre k cajas distintas, permitiendo vacías, equivale a colocar k−1 separadores entre r fichas: hay C(r+k−1,k−1). Con 3 fichas y 2 cajas hay cuatro resultados: (0,3),(1,2),(2,1),(3,0). Si cada caja debe recibir una, asigna primero k fichas y reparte las restantes. Para contar elementos de A o B usa |A|+|B|−|A∩B|; con tres conjuntos suma los individuales, resta intersecciones de pares y devuelve la triple. Los signos evitan contar más de una vez a quien pertenece a varias categorías.'},
 {title:'Calcular binomiales sin errores aritméticos',body:'La recurrencia de Pascal usa solamente sumas y funciona con cualquier módulo. La versión de una fila actualiza j hacia abajo para que C[j−1] aún pertenezca a la fila anterior. Con n=4, las filas son [1], [1,1], [1,2,1], [1,3,3,1], [1,4,6,4,1]. Para muchas consultas y módulo primo p con n<p, precalcula factoriales e inversos factoriales. La restricción n<p evita invertir un factorial cero módulo p. Para n≤60 todos los coeficientes binomiales caben en long long, aunque 60! no quepa: una fórmula correcta puede ser una implementación incorrecta si sus intermedios desbordan.'},
],{title:'Tres objetos distintos para contar',prompt:'Hay seis estudiantes. Cuenta: capitán y suplente distintos; un equipo de dos sin cargos; distribuciones de cuatro fichas idénticas entre tres mesas distintas permitiendo mesas vacías. Explica por qué las respuestas no usan la misma fórmula.',hints:['Los cargos distinguen orden.', 'Para fichas y mesas usa cuatro fichas y dos separadores.'],solution:'Los cargos dan 6·5=30 pares ordenados. Los equipos dan C(6,2)=15, porque cada equipo fue contado en dos órdenes. Las distribuciones dan C(4+3−1,3−1)=C(6,2)=15. Las últimas dos coinciden numéricamente, pero cuentan objetos diferentes mediante correspondencias diferentes. No puedes intercambiar sus explicaciones: una usa eliminar órdenes internos y la otra representar cantidades por separadores.'},{title:'Elegir representantes',prompt:'Lee n,k e imprime la cantidad exacta de subconjuntos de k estudiantes entre n distintos. Límites: 0 ≤ k ≤ n ≤ 60. No uses factoriales gigantes; calcula con Pascal.',hints:['C(n,k)=C(n−1,k−1)+C(n−1,k).', 'En una sola fila recorre k hacia abajo.'],solution:'Elige un estudiante distinguido. Los equipos que lo incluyen corresponden a elegir k−1 entre n−1; los que no lo incluyen corresponden a elegir k entre n−1. Esos casos son disjuntos y completos, de donde sale Pascal. La fila comprimida conserva el caso base C(0,0)=1. Tarda O(nk) y ocupa O(k). El comité vacío y elegir a todos tienen una sola forma.',tests:[{input:'7 3\n',output:'35\n'},{input:'0 0\n',output:'1\n'},{input:'60 30\n',output:'118264581564861424\n'}]});

add('intro-dp',[
 {title:'Una receta que empieza antes de la tabla',body:'Define con una oración qué significa dp[i]. Después pregunta qué información necesita el futuro: si dos historias llegan al mismo i y tienen exactamente las mismas opciones futuras, pueden compartir estado. Si una tiene una restricción adicional, como haber usado ya un pase especial, i solo no basta: agrega ese dato. Luego identifica la última decisión o la primera pendiente, deriva las transiciones y fija casos base. Solo después elige recursión con memoria o tabla iterativa. Una tabla llena de números no demuestra que el estado represente el problema correcto.'},
 {title:'Contar, minimizar y maximizar no se inicializan igual',body:'Para contar, un estado imposible aporta cero; el estado vacío válido suele aportar uno. Para minimizar, lo imposible debe valer infinito y el inicio cero. Para maximizar ganancias con cantidades exactas, un estado imposible puede necesitar menos infinito: poner cero permitiría soluciones que nunca existieron. En monedas [2,5], minimizar monedas para suma 3 debe responder imposible, no cero. Para suma 7, compara tomar una moneda 2 después de llegar a 5 o una 5 después de llegar a 2; ambas rutas producen dos monedas.'},
 {title:'Subproblemas repetidos y orden de evaluación',body:'La recursión ingenua de escalones recalcula muchas veces maneras(3),maneras(2),… y crece exponencialmente. Guardar cada respuesta reduce el trabajo a una evaluación por estado. La tabla de abajo hacia arriba hace explícito el orden de dependencias: dp[i] solo usa índices menores. La memoria recursiva además usa pila; una cadena larga de estados puede desbordarla. Si dp[a] depende de dp[b] y dp[b] de dp[a], no basta agregar memoria para resolver ese ciclo; revisa si debes modelar distancias, iteraciones o un estado más detallado.'},
 {title:'Cómo probar una recurrencia y recuperar decisiones',body:'Prueba por inducción: los casos base son correctos; asume correctos los estados anteriores; muestra que cada solución de i termina en uno de los casos considerados y que cada transición produce una solución válida. En conteo, verifica además que los casos no se traslapen. Para reconstruir una solución óptima, guarda la decisión que consiguió el mejor valor y retrocede desde el objetivo. El tiempo se estima como número de estados por transiciones por estado, incluyendo el costo de cada transición. Optimizar memoria antes de entender qué fila necesitas suele introducir errores innecesarios.'},
],{title:'Un estado que olvidó algo',prompt:'Quieres subir n peldaños con saltos de uno o dos, pero no puedes usar dos saltos de dos consecutivos. Explica por qué dp[i] con la recurrencia usual no alcanza. Diseña el estado y calcula el resultado para n=4.',hints:['El futuro necesita saber si el último salto fue de dos.', 'Enumera primero los cinco recorridos normales para cuatro.'],solution:'dp[i][b] guarda maneras de llegar a i, donde b indica si el último salto fue de dos. Un salto de uno llega a dp[i+1][0] desde cualquiera de los dos estados. Un salto de dos solo llega a dp[i+2][1] desde b=0. Empieza con dp[0][0]=1. Para n=4, de 1111,112,121,211,22 se prohíbe 22 y quedan cuatro. Dos historias con igual altura pero distinto último salto no tienen las mismas opciones futuras, por eso deben separarse.'},{title:'Escalera de entrenamiento',prompt:'Lee n e imprime cuántas secuencias de saltos de uno o dos peldaños llegan exactamente a la altura n. En este ejercicio no hay restricciones entre saltos. Límites: 0 ≤ n ≤ 90. El recorrido vacío cuenta como una forma para n=0.',hints:['Separa por tamaño del último salto.', 'dp[0]=1 permite construir el primer salto.'],solution:'Todo recorrido a i termina en un salto de uno desde i−1 o en uno de dos desde i−2. Son casos disjuntos que cubren todos los recorridos. La recurrencia suma ambos, omitiendo índices negativos. Construir ascendentemente cuesta O(n) tiempo y O(n) memoria. Para n≤90 la respuesta cabe en long long. Es importante no aplicar la restricción del ejercicio de razonamiento: aquí ambos saltos se pueden repetir libremente.',tests:[{input:'5\n',output:'8\n'},{input:'0\n',output:'1\n'},{input:'90\n',output:'4660046610375530309\n'}]});

add('knapsack',[
 {title:'Definir si el peso es exacto o máximo',body:'La frase «peso a lo sumo W» permite dejar espacio vacío. Una tabla dp[c] de mejor valor con capacidad máxima c puede empezar toda en cero porque escoger nada es válido para cualquier capacidad. Si quieres peso exactamente c, solo dp[0]=0 es válido al principio y las otras entradas deben marcarse imposibles. Confundir estos dos significados produce respuestas ficticias. Para objetos de pesos 3 y 5, el peso exacto 4 es imposible aunque una mochila de capacidad 4 sí pueda guardar el objeto de peso 3.'},
 {title:'Traza de una fila y dirección del ciclo',body:'Con un solo objeto de peso 2, valor 3 y capacidad 4, una actualización ascendente pone dp[2]=3 y después dp[4]=dp[2]+3=6: tomó dos copias del mismo objeto. En mochila 0/1 esto es ilegal. Descendiendo, dp[4] consulta el dp[2] anterior a procesar el objeto, todavía cero, y queda 3. En mochila ilimitada, en cambio, esa reutilización es exactamente lo deseado y el ciclo ascendente es correcto. La dirección no es un truco de memoria: expresa qué objetos están permitidos en el estado del que vienes.'},
 {title:'Cambiar la dimensión cuando cambia el límite',body:'Si W llega a mil millones pero la suma de valores es a lo sumo 100000, no reserves W entradas. Define peso[v] como el mínimo peso necesario para obtener exactamente valor v. Inicializa peso[0]=0 y lo demás infinito; por cada objeto recorre valores descendiendo. Al final busca el mayor v cuyo peso[v]≤W. El costo es O(n·sumaValores). Si n es pequeño, alrededor de 40, pero pesos y valores son enormes, encuentro a mitad puede ser adecuado. Las restricciones deciden qué variable puede convertirse en dimensión de la tabla.'},
 {title:'Por qué ordenar por proporción no basta',body:'Con capacidad 4 y objetos (peso,valor)=(3,5),(2,3),(2,3), escoger primero la mayor proporción toma (3,5) y deja espacio inutilizable: valor 5. Los otros dos juntos valen 6. La estrategia por valor/peso sirve para mochila fraccionaria, donde puedes tomar pedazos, pero no garantiza la variante 0/1. La recurrencia correcta compara explícitamente tomar o no tomar cada objeto. Para reconstruir cuáles se eligieron, conserva filas o decisiones; una sola fila de valores puede perder información sobre cuándo se produjo cada mejora.'},
],{title:'La misma tabla, dos problemas',prompt:'Con capacidad 6 y objetos (2,3),(3,4),(4,5), encuentra el óptimo 0/1 y el óptimo ilimitado. Explica el efecto de recorrer capacidades ascendiendo y por qué ordenar por valor no demuestra la solución.',hints:['En 0/1 puedes elegir los objetos de peso 2 y 4.', 'En ilimitada puedes repetir el de peso 2.'],solution:'En 0/1, los objetos de pesos 2 y 4 dan valor 8. En ilimitada, tres copias del objeto de peso 2 dan valor 9; dos copias del de peso 3 darían 8. Actualizar ascendiendo permite que el estado previo ya contenga el mismo objeto, modelando copias ilimitadas. Ordenar por valor no contempla cómo se combinan pesos y espacio restante: la prueba proviene de separar todas las soluciones entre tomar o no tomar el objeto actual.'},{title:'Equipo para la delegación',prompt:'Lee n,W y n pares peso valor. Cada objeto puede elegirse a lo sumo una vez. Imprime el mayor valor total con peso a lo sumo W. Límites: 0 ≤ n ≤ 100; 0 ≤ W ≤ 10000; 1 ≤ peso ≤ 10000; 0 ≤ valor ≤ 1000000000.',hints:['Inicializa dp[c]=0 para capacidad máxima.', 'Recorre capacidades desde W hacia el peso del objeto.'],solution:'Después de cada objeto, dp[c] es el óptimo usando solo los objetos procesados. La transición toma el máximo entre no elegirlo y sumarlo a una solución anterior que deja espacio suficiente. Descender capacidades evita reutilizarlo. Cuesta O(nW) tiempo y O(W) memoria; los valores se acumulan en long long. Elegir ningún objeto siempre es válido, incluso con capacidad cero.',tests:[{input:'3 6\n2 3\n3 4\n4 5\n',output:'8\n'},{input:'1 4\n2 3\n',output:'3\n'},{input:'2 0\n1 8\n2 9\n',output:'0\n'}]});

add('paths-grids',[
 {title:'Una cuadrícula puede esconder un orden topológico',body:'Moverse solo hacia abajo o a la derecha aumenta fila+columna en uno. Por tanto ninguna secuencia regresa a una celda anterior y no hay ciclos. Puedes procesar por filas, por columnas o por diagonales siempre que arriba e izquierda estén resueltos antes. Si agregas movimientos hacia arriba, esa propiedad desaparece; no basta añadir otra entrada a la fórmula. Para contar rutas arbitrarias podrían existir infinitas por repetir ciclos. Para buscar distancia mínima con pasos uniformes usarías BFS en el grafo de celdas.'},
 {title:'Casos base que el dibujo aclara',body:'El origen tiene una forma de alcanzarse: no hacer movimientos. Si está bloqueado, tiene cero. En la primera fila solo puedes venir de la izquierda; después del primer obstáculo todas sus celdas quedan con cero caminos por esa fila. La primera columna tiene el caso análogo. En un tablero 2×3 libre, la primera fila es [1,1,1] y la segunda [1,2,3]. Bloqueando la celda superior central, las filas quedan [1,0,0] y [1,1,1]. No inicialices toda la primera fila con unos sin revisar obstáculos.'},
 {title:'Cambiar qué guardas, conservar la estructura',body:'Para minimizar el costo de un camino, guarda costo[f][c]=precio[f][c]+min(costo de arriba,costo de izquierda), y asigna infinito a obstáculos o entradas inválidas. Para maximizar una recompensa usa máximo y menos infinito. Si además hay un recurso que puedes usar una vez, como atravesar una pared, agrega una dimensión indicando si ya se gastó. La cuadrícula solamente organiza transiciones: el significado del estado y la operación para combinar resultados dependen de lo que pida el problema.'},
 {title:'Memoria comprimida y pruebas de consistencia',body:'Con una fila, antes de actualizar columna c, dp[c] representa arriba y dp[c−1] ya representa izquierda. Esa mezcla de una parte vieja y otra nueva es intencional. Al encontrar una pared, debes poner dp[c]=0 para que el valor de arriba no atraviese el obstáculo ni se propague a la derecha. Los conteos crecen rápidamente, por eso el ejercicio pide módulo 1000000007. Prueba origen bloqueado, destino bloqueado, una sola fila y una celda. Para tableros pequeños compara con enumerar todas las cadenas de movimientos y descartar las que tocan paredes.'},
],{title:'Una pared cambia varias respuestas',prompt:'Calcula toda la tabla de caminos de un tablero 3×4 donde solo está bloqueada la celda (1,1), usando índices desde cero y movimientos abajo/derecha. ¿Cuántos caminos llegan al destino? Explica por qué poner dp[1]=0 al pasar por la pared es indispensable.',hints:['La primera fila tiene cuatro unos.', 'La celda bloqueada recibe cero, aunque tenga vecinos alcanzables.'],solution:'Las filas de la tabla son [1,1,1,1], [1,0,1,2] y [1,1,2,4]. Hay cuatro caminos al destino. Al comprimir memoria, dp[1] contenía el número de caminos a la celda de arriba; conservarlo permitiría atravesar la pared y sumarlo en las celdas siguientes. La pared debe borrar ese valor. La recurrencia no solo cuenta llegadas válidas: también excluye explícitamente los estados prohibidos.'},{title:'Caminos del laboratorio',prompt:'Lee n,m y n filas de m caracteres: punto libre, # bloqueado. Desde la esquina superior izquierda solo puedes moverte abajo o derecha hasta la inferior derecha. Imprime la cantidad de caminos módulo 1000000007. Límites: 1 ≤ n,m ≤ 1000.',hints:['La pared recibe cero caminos.', 'Cada celda libre suma arriba e izquierda; trata el origen.'],solution:'Todo camino al destino de una celda entra por arriba o izquierda, dos casos disjuntos. La tabla ascendente acumula esos conteos y elimina obstáculos. Una sola fila conserva exactamente las dos dependencias necesarias. El costo es O(nm) tiempo y O(m) memoria. Si el origen o destino están bloqueados la respuesta termina en cero sin una ruta artificial.',tests:[{input:'3 4\n....\n.#..\n....\n',output:'4\n'},{input:'1 1\n.\n',output:'1\n'},{input:'1 2\n#.\n',output:'0\n'}]});

add('lis',[
 {title:'Subsecuencia no significa subarreglo',body:'Una subsecuencia conserva el orden de las posiciones originales, pero permite omitir elementos. En [3,1,4,2,5], [1,2,5] es una subsecuencia creciente de longitud 3, aunque no sea contigua. El modelo cuadrático define dp[i] como la mayor longitud creciente que termina exactamente en i: dp[i]=1+max(dp[j]) para j<i con a[j]<a[i], o 1 si no hay candidato. La respuesta es el máximo sobre todos los finales. Esta versión O(n²) es útil para entender y verificar la solución rápida sobre casos pequeños.'},
 {title:'Por qué basta conservar el menor final',body:'Entre dos subsecuencias crecientes de igual longitud, la que termina en un valor menor permite al menos las mismas extensiones futuras. Por eso tails[len−1] guarda el menor final posible de una subsecuencia de longitud len en el prefijo procesado. No guarda una única subsecuencia: sus entradas pueden provenir de historias distintas. Para [3,5,6,2], tails termina [2,5,6], que no aparece en ese orden en los datos. Aun así la longitud 3 es correcta porque existía [3,5,6].'},
 {title:'Actualizar por una frontera binaria',body:'Al leer x, busca la primera posición p con tails[p]≥x. Si no existe, x extiende la subsecuencia más larga y se agrega al final. Si existe, reemplazar tails[p] por x mejora o conserva el final para longitud p+1. Los finales anteriores son menores que x, así que existe una subsecuencia de longitud p a la que puedes añadirlo. Para [3,1,4,2,5], tails pasa por [3],[1],[1,4],[1,2],[1,2,5]. Usamos lower_bound para crecimiento estricto; si se permite igualdad, cambia a upper_bound.'},
 {title:'Reconstruir y tratar duplicados',body:'Para recuperar los elementos, guarda el índice del último elemento que representa cada longitud y, para cada posición i, el índice predecesor de la subsecuencia que extiende. Cuando x ocupa p, su predecesor es el representante de p−1 antes de actualizar. Retrocede desde el representante de la longitud máxima y luego invierte el resultado. En [2,2,2], la LIS estricta mide 1; la no decreciente mide 3. El algoritmo rápido cuesta O(n log n) tiempo y O(n) memoria. Su justificación depende de dominancia de finales, no de que ordenar los datos preserve el problema.'},
],{title:'La tabla de finales no es la respuesta',prompt:'Procesa [4,7,9,2,5,8] con tails. Da el arreglo después de cada elemento y una subsecuencia creciente real de longitud máxima. Explica por qué ordenar primero el arreglo cambiaría el problema.',hints:['Busca el primer final al menos tan grande como el nuevo valor.', 'Una subsecuencia debe respetar el orden de las posiciones.'],solution:'Los estados son [4],[4,7],[4,7,9],[2,7,9],[2,5,9],[2,5,8]. La longitud máxima es 3; una subsecuencia real es [2,5,8], otra [4,7,9]. Ordenar daría [2,4,5,7,8,9], longitud 6, pero ese orden no existe en la entrada. tails resume posibilidades de extensión por longitud; no autoriza reorganizar los valores originales.'},{title:'Marcas en ascenso',prompt:'Lee n y n marcas. Imprime la longitud máxima de una subsecuencia estrictamente creciente. Puedes omitir valores, conservando su orden original. Límites: 0 ≤ n ≤ 200000; |marca| ≤ 1000000000000.',hints:['Conserva el menor final por longitud.', 'Los valores iguales no extienden una subsecuencia estricta.'],solution:'La menor terminación domina a cualquier terminación mayor de la misma longitud para todas las extensiones futuras. Por eso sustituir una entrada de tails no pierde una longitud posible. lower_bound encuentra dónde incorporar cada valor manteniendo tails ordenado. La cantidad de entradas al final es la longitud óptima. Tarda O(n log n) y usa O(n) memoria; el arreglo vacío responde cero.',tests:[{input:'6\n4 7 9 2 5 8\n',output:'3\n'},{input:'4\n2 2 2 2\n',output:'1\n'},{input:'0\n',output:'0\n'}]});

add('dp-bitmasks',[
 {title:'Qué información contiene el subconjunto',body:'Supón n estudiantes y n tareas, con un costo por asignación. Procesa estudiantes en orden fijo: la máscara guarda qué tareas ya se asignaron. Si tiene k bits, ya atendiste exactamente a los primeros k estudiantes. No necesitas otra dimensión para k porque puedes deducirla. Define dp[mask] como el costo mínimo de esa asignación parcial. Un estado no debe recordar información redundante, pero sí toda la que afecte las opciones futuras. En este modelo saber qué tareas están ocupadas basta; el orden en que las elegiste ya no importa.'},
 {title:'Transición, base y demostración',body:'Empieza con dp[0]=0 y los demás imposibles. Para cada tarea j ausente de mask, actualiza dp[mask|(1<<j)] con dp[mask]+costo[k][j], donde k es la cantidad de bits de mask. Cada asignación completa tiene una última tarea asignada al estudiante n−1; retirarla da un estado anterior válido. A la inversa, cualquier transición asigna una tarea libre al siguiente estudiante, de modo que conserva la validez. Inducción sobre cantidad de bits demuestra la optimalidad. Los estados numéricamente mayores incluyen el bit nuevo, por lo que recorrer máscaras ascendiendo respeta las dependencias.'},
 {title:'Un ejemplo y una dimensión que a veces falta',body:'Para costos [[4,1,7],[2,5,3],[6,4,2]], asignar tareas 1,0,2 a estudiantes 0,1,2 cuesta 1+2+2=5. dp[010]=1 y dp[011]=3; añadir tarea 2 produce dp[111]=5. En un recorrido que visita ciudades, en cambio, el mismo subconjunto puede terminar en ciudades diferentes y eso cambia el costo de continuar. Allí usa dp[mask][última]. Para caminos hamiltonianos, las transiciones agregan una ciudad vecina no visitada. Contar recorridos o minimizar su costo cambia la operación de combinación, pero mantiene la necesidad de recordar el extremo.'},
 {title:'Cuánto cabe y cuándo aparecen tres a la n',body:'La asignación tiene 2 elevado a n estados y hasta n transiciones por estado: O(n·2 elevado a n) tiempo y O(2 elevado a n) memoria. Con n=20 hay aproximadamente un millón de estados. Una tabla por máscara y último vértice multiplica la memoria por n. Si para cada máscara enumeras todos sus subgrupos, el total puede ser 3 elevado a n, porque cada elemento puede quedar fuera, en el subgrupo o en el resto. Nunca supongas que todo algoritmo con máscaras tiene el mismo costo. Usa un infinito suficientemente grande y no sumes costos a estados imposibles.'},
],{title:'Encuentra el estado insuficiente',prompt:'Para hallar la ruta más barata que visita exactamente un conjunto de ciudades, una propuesta guarda solo dp[mask]. Explica con dos recorridos sobre el mismo conjunto por qué puede faltar información. ¿Por qué esa dimensión extra no es necesaria en la asignación de tareas?',hints:['La siguiente arista sale de la ciudad donde terminaste.', 'En asignación, el siguiente estudiante está fijado por la cantidad de tareas ocupadas.'],solution:'Dos rutas que visitan {A,B,C} pueden terminar en A o en C. Si la siguiente ciudad D está cerca de A y lejos de C, sus mejores continuaciones tienen costos distintos; guardar solo el menor costo parcial podría descartar la ruta que permite el mejor total. Hace falta el último vértice. En asignación no hay una arista desde la tarea anterior a la siguiente: el costo depende del estudiante k y de la nueva tarea j. k se deduce del número de bits, por lo que mask basta.'},{title:'Asignar retos a estudiantes',prompt:'Lee n y una matriz n×n de costos. Asigna a cada estudiante una tarea distinta y usa todas las tareas. Imprime el costo total mínimo. Límites: 1 ≤ n ≤ 18; 0 ≤ costo ≤ 1000000000. Filas son estudiantes y columnas tareas.',hints:['dp[mask] atiende a los primeros popcount(mask) estudiantes.', 'Agrega una tarea todavía libre.'],solution:'Cada transición asigna exactamente la siguiente persona y una tarea no usada. Todos los emparejamientos completos aparecen mediante una única secuencia en el orden de estudiantes, y el mínimo compara sus costos. La DP cuesta O(n·2 elevado a n) y ocupa O(2 elevado a n). Los costos usan long long y el estado vacío vale cero.',code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<long long>> c(n, vector<long long>(n));\n    for (auto &r : c)\n        for (auto &x : r)\n            cin >> x;\n    int z = 1 << n;\n    const long long INF = 4000000000000000000LL;\n    vector<long long> d(z, INF);\n    d[0] = 0;\n    for (int mask = 0; mask < z; mask++) {\n        int k = 0;\n        for (int bits = mask; bits; bits &= bits - 1)\n            k++;\n        if (k == n)\n            continue;\n        for (int j = 0; j < n; j++)\n            if (!(mask & (1 << j)))\n                d[mask | (1 << j)] = min(d[mask | (1 << j)], d[mask] + c[k][j]);\n    }\n    cout << d[z - 1] << \"\\n\";\n}",tests:[{input:'3\n4 1 7\n2 5 3\n6 4 2\n',output:'5\n'},{input:'1\n9\n',output:'9\n'},{input:'2\n0 0\n0 0\n',output:'0\n'}]});

add('dp-ranges',[
 {title:'Intervalos que resumen una parte contigua',body:'Al fusionar montones adyacentes, el conjunto de piedras de cada montón intermedio siempre corresponde a un intervalo original. Define dp[l][r] como el costo mínimo de convertir los montones l,…,r en uno. El costo de una fusión es la cantidad total de piedras de los dos montones fusionados. No basta escoger siempre el par adyacente de menor suma: una elección local cambia qué pares serán vecinos después. La estructura de intervalos permite considerar todas las últimas divisiones sin enumerar cada orden completo de operaciones.'},
 {title:'Mira la última operación, no la primera',body:'Justo antes de la última fusión del intervalo [l,r], quedan dos montones: uno procede de [l,k] y otro de [k+1,r] para algún k. Por tanto dp[l][r]=mínimo sobre k de dp[l][k]+dp[k+1][r]+suma(l,r). El último costo no depende de k porque al final se fusionan todas las piedras del intervalo. Los prefijos calculan suma(l,r) en O(1). El caso base dp[i][i]=0 representa que un montón ya está fusionado. Enumeramos longitudes crecientes para tener resueltos ambos subintervalos.'},
 {title:'Traza y diferencia con fusionar libremente',body:'Para [3,2,4], los intervalos de longitud dos cuestan 5 y 6. Para [0,2], separar tras el primer montón cuesta 0+6+9=15; separar tras el segundo cuesta 5+0+9=14. La respuesta es 14. La cola de prioridad de fusiones libres no se aplica porque aquí solo se unen vecinos. En [1,100,1], fusionar los dos unos sería barato pero ilegal; cualquier primera fusión válida cuesta 101 y la final 102, total 203. La restricción de adyacencia es precisamente lo que hace útil el estado por intervalo.'},
 {title:'Otros intervalos y costo cúbico',body:'Hay O(n²) intervalos y O(n) cortes por intervalo, por lo que el tiempo es O(n³) y la memoria O(n²). Para n=300 resulta razonable; para n=200000 no. El mismo esquema aparece al parentizar productos de matrices: dividir el producto en dos partes y añadir el costo de multiplicar sus resultados, que sí depende de dimensiones. Otras DP comparan extremos para decidir palíndromos. No apliques optimizaciones de intervalos solo por su forma: requieren propiedades adicionales de los costos y de dónde aparece el corte óptimo.'},
],{title:'Comprueba todos los últimos cortes',prompt:'Calcula el costo óptimo para fusionar [2,1,3] con adyacencia. Escribe los dos candidatos de la última fusión. Después explica por qué el algoritmo de juntar siempre los dos menores globales es inválido para [1,100,1].',hints:['Los intervalos de dos montones cuestan su suma.', 'La última fusión del intervalo completo cuesta 6.'],solution:'dp[0][1]=3 y dp[1][2]=4. El corte k=0 produce 0+4+6=10; el corte k=1 produce 3+0+6=9. La respuesta es 9, fusionando primero 2 y 1. En [1,100,1], los dos menores no son adyacentes: fusionarlos viola el enunciado. Ambos órdenes permitidos cuestan 101+102=203. Un algoritmo correcto para fusiones libres no se vuelve correcto para fusiones adyacentes por usar los mismos costos.'},{title:'Montones en una fila',prompt:'Lee n y n tamaños positivos. Solo puedes fusionar dos montones vecinos y pagas la suma de sus tamaños. Imprime el costo total mínimo para dejar uno. Límites: 1 ≤ n ≤ 250; 1 ≤ tamaño ≤ 1000000000.',hints:['Define un estado para cada intervalo.', 'Prueba todos los cortes que podrían preceder a la última fusión.'],solution:'Toda última operación divide el intervalo en dos subintervalos no vacíos. Optimizar ambos independientemente y añadir la suma considera todas las posibilidades sin omitir ninguna. Procesamos por longitud, usando prefijos para cada suma. El costo es O(n³) y la memoria O(n²); long long guarda los costos acumulados.',code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nint main() {\n    int n;\n    cin >> n;\n    vector<long long> p(n + 1);\n    for (int i = 0; i < n; i++) {\n        long long x;\n        cin >> x;\n        p[i + 1] = p[i] + x;\n    }\n    vector<vector<long long>> d(n, vector<long long>(n));\n    for (int len = 2; len <= n; len++)\n        for (int l = 0; l + len <= n; l++) {\n            int r = l + len - 1;\n            d[l][r] = 4000000000000000000LL;\n            for (int k = l; k < r; k++)\n                d[l][r] = min(d[l][r], d[l][k] + d[k + 1][r] + p[r + 1] - p[l]);\n        }\n    cout << d[0][n - 1] << \"\\n\";\n}",tests:[{input:'3\n2 1 3\n',output:'9\n'},{input:'1\n8\n',output:'0\n'},{input:'3\n1 100 1\n',output:'203\n'}]});

add('digit-dp',[
 {title:'Contar representaciones sin enumerar números',body:'Queremos contar enteros entre 0 y N cuya suma de dígitos es divisible por D. Si N tiene 18 cifras, recorrer todos los enteros es imposible; construir sus dígitos con estados compartidos sí puede funcionar. Escribe N como cadena. Un estado necesita posición, residuo de la suma y si el prefijo todavía está igual al de N. Esa última marca se llama límite activo: si ya elegimos un dígito menor, los siguientes pueden ir de 0 a 9 sin volver a comparar el número completo.'},
 {title:'Transición que respeta el límite',body:'Desde (pos,residuo,igual), el mayor dígito permitido es N[pos] si igual es verdadero, o 9 si ya somos menores. Por cada dígito d, el nuevo residuo es (residuo+d)%D. La nueva igualdad exige que igual fuera verdadera y d coincidiera con N[pos]. Al terminar todas las posiciones, el estado aporta uno si el residuo es cero y cero en otro caso. Empezamos con residuo 0 y límite activo. Cada cadena de dígitos representa exactamente un número dentro del rango, de modo que sumar transiciones cuenta sin duplicaciones.'},
 {title:'Ceros iniciales y rangos',body:'Para suma de dígitos, añadir ceros a la izquierda no altera la propiedad: podemos representar 7 como 007. El número cero queda contado y tiene suma cero. Si el ejercicio excluye cero, réstalo al final. Para propiedades como «no aparecen dos dígitos iguales consecutivos», los ceros iniciales sí necesitan tratamiento: agrega una marca de si el número ya empezó, para no confundir relleno con dígitos reales. Para un rango [L,R], calcula F(R)−F(L−1), definiendo F(−1)=0. Mantén idéntica convención sobre cero en ambas cuentas.'},
 {title:'Traza, memoria y otros autómatas',body:'Con N=23 y D=3, sirven 0,3,6,9,12,15,18,21: ocho números. El prefijo inicial 1 ya es menor que 2, así que su segundo dígito puede ser cualquiera; el prefijo 2 solo permite hasta 3. El algoritmo tiene O(cifras·D·2) estados y diez transiciones por estado. Puedes comprimir la dimensión de posición en dos capas. En otros problemas, el estado resume el último dígito, cuántos ceros aparecieron o un estado de patrón prohibido. Agregar demasiada historia multiplica estados; conserva únicamente información que cambie las continuaciones válidas.'},
],{title:'¿Hace falta una marca de inicio?',prompt:'Para contar números cuya suma de dígitos es múltiplo de 3, explica por qué 007 y 7 tienen el mismo estado relevante. ¿Qué cambia si quieres contar números que contienen exactamente un dígito cero? Calcula F(12) para la primera propiedad incluyendo cero.',hints:['Los ceros iniciales suman cero, pero no son dígitos escritos normalmente.', 'Los múltiplos de tres hasta 12 sirven para verificar.'],solution:'Los ceros iniciales no cambian la suma, así que para esa propiedad pueden procesarse normalmente. Para contar ceros escritos, 007 no debe tener dos ceros adicionales: necesitas recordar si ya comenzó el número y decidir cómo representar el número cero al terminar. Para suma divisible por 3 hasta 12 sirven 0,3,6,9,12; F(12)=5. Los estados deben representar el enunciado, no solamente la cadena rellenada que usa el algoritmo.'},{title:'Suma de dígitos equilibrada',prompt:'Lee N y D. Cuenta los enteros x con 0 ≤ x ≤ N cuya suma de dígitos sea divisible por D. Incluye cero. Límites: 0 ≤ N ≤ 1000000000000000000; 1 ≤ D ≤ 100. Imprime la cantidad exacta.',hints:['Usa residuo de la suma y una marca de igualdad con N.', 'Los ceros iniciales no afectan la suma.'],solution:'Procesamos todos los dígitos de N. Los estados cuentan prefijos según residuo y si permanecen iguales al límite. Elegir un dígito actualiza ambos datos y respeta la cota. Cada entero de 0 a N tiene una representación rellenada única; por eso la suma de los estados finales de residuo cero es exacta. Tiempo O(cifras·D·10) y memoria O(D); el conteo cabe en long long bajo estos límites.',code:"#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\nint main() {\n    string s;\n    int D;\n    cin >> s >> D;\n    vector<vector<long long>> dp(2, vector<long long>(D));\n    dp[1][0] = 1;\n    for (char ch : s) {\n        vector<vector<long long>> nd(2, vector<long long>(D));\n        for (int eq = 0; eq < 2; eq++)\n            for (int r = 0; r < D; r++) {\n                int lim = eq ? ch - '0' : 9;\n                for (int d = 0; d <= lim; d++)\n                    nd[eq && (d == ch - '0')][(r + d) % D] += dp[eq][r];\n            }\n        dp.swap(nd);\n    }\n    cout << dp[0][0] + dp[1][0] << \"\\n\";\n}",tests:[{input:'23 3\n',output:'8\n'},{input:'0 7\n',output:'1\n'},{input:'1000000000000000000 1\n',output:'1000000000000000001\n'}]});

add('unweighted-shortest-paths',[
 {title:'La cola es una garantía de orden',body:'BFS no elige arbitrariamente qué vértice procesar. La cola mantiene primero todos los de distancia d y después los de d+1 que ellos descubren. Si hubiera una ruta más corta al vecino nuevo, su vértice anterior tendría una distancia menor y habría sido procesado antes. Esta contradicción demuestra que la primera distancia asignada es óptima cuando todas las aristas cuestan uno. En grafos dirigidos guarda únicamente las direcciones permitidas. En problemas de estados, una arista puede representar una operación válida, no necesariamente un camino físico.'},
 {title:'Reconstruir y comenzar desde varios orígenes',body:'Cuando descubres v desde u, guarda padre[v]=u. Para recuperar una ruta al destino, sigue padres hasta el origen y luego invierte la lista. Si existen varias rutas mínimas, obtienes una de ellas según el orden de vecinos. Para distancia a la fuente más cercana entre varias fuentes, mete todas al principio con distancia cero. Las capas se expanden simultáneamente y el mismo argumento prueba el mínimo a cualquiera. No ejecutes una BFS completa por fuente si solo necesitas ese mínimo conjunto.'},
 {title:'Aristas de costo cero o uno',body:'Con pesos 0 y 1, una arista de costo cero no debe esperar detrás de todos los estados de distancia mayor. Usa una deque: al mejorar por peso cero inserta al frente, y por peso uno al final. Mantén distancias y permite mejorarlas; marcar visto una sola vez al descubrir puede ser incorrecto. En 0→1 con costo 1, 0→2 con costo 0 y 2→1 con costo 0, la primera propuesta a 1 cuesta 1 pero la óptima es 0. La deque conserva el orden de capas adecuado y permite O(n+m) tiempo.'},
 {title:'Modelar el estado antes de recorrer',body:'Si puedes romper una pared una vez, dos visitas a la misma celda no son equivalentes: llegar con el permiso disponible puede permitir una ruta futura diferente. Crea estados (fila,columna,usado) y distancias separadas. Para horarios periódicos, quizá necesites (vértice,tiempo módulo periodo). BFS minimiza cantidad de transiciones, así que cada transición debe representar el mismo costo. Si una acción consume cinco minutos y otra uno, tratarlas como una arista cada una resolvería cantidad de acciones, no tiempo. Pesos generales no negativos requieren Dijkstra.'},
],{title:'La visita temprana puede no ser definitiva',prompt:'En el grafo dirigido 0→1 de peso 1, 0→2 de peso 0, 2→1 de peso 0, 1→3 de peso 1, encuentra las distancias desde 0. Explica por qué una BFS común y una marca definitiva al descubrir no son suficientes.',hints:['La ruta 0→2→1 usa más aristas pero cuesta menos.', 'Una mejora de costo cero debe procesarse antes de distancias mayores.'],solution:'Las distancias son [0,0,0,1]. Al inspeccionar 0→1 podría asignarse provisionalmente 1, pero 0→2→1 mejora a 0. Una BFS común minimiza aristas y preferiría la arista directa, ignorando los costos. Una marca definitiva impediría la mejora. BFS 0–1 compara nuevas distancias y coloca al frente las mejoras de costo cero, manteniendo la estructura de distancias que la cola ordinaria ya no garantiza.'},{title:'Distancias entre sedes',prompt:'Lee n,m y m aristas no dirigidas entre vértices de 0 a n−1. Cada arista cuesta un paso. Imprime las distancias mínimas desde 0 a todos los vértices, usando −1 para inalcanzables. Límites: 1 ≤ n ≤ 200000; 0 ≤ m ≤ 300000.',hints:['Inicializa distancias en −1 y la del origen en cero.', 'La primera llegada de BFS es mínima para pesos uniformes.'],solution:'La cola procesa vértices por capas de distancia. Todo vecino aún desconocido recibe distancia del actual más uno y se encola una sola vez. Los vértices no descubiertos quedan en −1. El tiempo y la memoria son O(n+m), y el grafo se guarda en ambas direcciones porque las conexiones son no dirigidas.',tests:[{input:'5 3\n0 1\n1 2\n0 3\n',output:'0 1 2 1 -1\n'},{input:'1 0\n',output:'0\n'},{input:'4 4\n0 1\n0 2\n1 3\n2 3\n',output:'0 1 1 2\n'}]});

add('dsu',[
 {title:'Representantes no son etiquetas inmutables',body:'DSU mantiene una partición: cada elemento pertenece a exactamente un conjunto. Un bosque de padres conduce desde cada elemento hasta una raíz representante. Dos elementos están conectados si find devuelve la misma raíz. Esa raíz puede cambiar después de unir conjuntos, así que no la guardes como etiqueta permanente fuera de la estructura. El árbol interno de DSU no es el grafo original: sus padres son decisiones del algoritmo y no tienen por qué corresponder a aristas del enunciado.'},
 {title:'Unión por tamaño y compresión',body:'Sin una regla, unir 1 con 2, luego 2 con 3 y así sucesivamente puede formar una cadena. Unión por tamaño conecta la raíz del conjunto menor bajo la del mayor; cuando un elemento aumenta de profundidad, el tamaño de su conjunto al menos se duplica. Compresión de caminos hace que find conecte directamente con la raíz todos los vértices del camino visitado. Juntas dan costo amortizado O(α(n)), prácticamente constante. Amortizado describe una secuencia de operaciones; no promete que cada llamada individual tenga exactamente el mismo costo.'},
 {title:'Contar componentes y detectar ciclos',body:'Empieza con n componentes. Cada unión exitosa entre raíces diferentes reduce el contador en uno; unir elementos ya conectados no lo cambia. Para conexiones 0−1,1−2,0−2 sobre cuatro vértices, las cantidades son 3,2,2. La tercera arista conecta vértices que ya tenían un camino, así que crea un ciclo en un grafo no dirigido. Esto permite construir bosques y aparece en Kruskal. Puedes guardar tamaño, suma o máximo en la raíz y combinar esos datos al unir, siempre consultando primero el representante actual.'},
 {title:'Qué no resuelve la estructura básica',body:'DSU responde conectividad bajo inserciones, pero no encuentra por sí sola la ruta entre dos vértices ni la distancia mínima. Tampoco permite borrar una arista fácilmente: una unión olvida qué conexión concreta mantenía unidas las partes. Algunos problemas de borrados se resuelven procesando operaciones al revés, convirtiéndolas en inserciones; otros requieren rollback y una organización adicional. No confundas conectividad dirigida con pertenecer al mismo conjunto: u→v no implica poder regresar. Las condiciones del problema deben corresponder a una equivalencia simétrica.'},
],{title:'Actualiza el contador correctamente',prompt:'Con cinco vértices 0,…,4, procesa uniones (0,1),(2,3),(1,2),(0,3),(4,4). Da el número de componentes tras cada una y explica cuáles deben devolver falso en join.',hints:['Una unión exitosa junta dos raíces distintas.', 'Un lazo no agrega conectividad.'],solution:'Los contadores son 4,3,2,2,2. Tras la tercera operación, {0,1,2,3} es un conjunto y {4} otro. (0,3) devuelve falso porque ambos ya están conectados; (4,4) también porque es el mismo elemento. Reducir siempre el contador por cada arista daría cero o valores negativos aunque no se hayan unido nuevos conjuntos. El retorno de join expresa si la partición cambió, no si la operación estaba bien formada.'},{title:'Grupos tras nuevas conexiones',prompt:'Lee n,m y m conexiones no dirigidas, con extremos de 0 a n−1. Imprime el número de componentes después de agregar todas. Se permiten conexiones repetidas y lazos. Límites: 1 ≤ n ≤ 200000; 0 ≤ m ≤ 300000.',hints:['Inicialmente cada vértice es su propio conjunto.', 'Resta uno solo cuando join conecta raíces distintas.'],solution:'La estructura comienza con la partición discreta. Cada arista obliga a que sus extremos pertenezcan al mismo conjunto, y unir sus componentes cumple exactamente esa condición. Al terminar la equivalencia coincide con alcanzabilidad del grafo. Unión por tamaño y compresión permiten O((n+m)α(n)) tiempo y O(n) memoria; no hace falta almacenar todas las aristas.',tests:[{input:'5 5\n0 1\n2 3\n1 2\n0 3\n4 4\n',output:'2\n'},{input:'1 0\n',output:'1\n'},{input:'3 3\n0 1\n1 2\n2 0\n',output:'1\n'}]});

add('toposort',[
 {title:'Dependencias que no admiten contradicciones',body:'Una arista u→v significa que u debe aparecer antes que v. Un orden topológico enumera todos los vértices respetando todas esas restricciones. Puede haber muchos órdenes válidos: si dos tareas no dependen entre sí, quizá puedan intercambiarse. Un ciclo dirigido exige A antes de B, B antes de C y C antes de A, contradicción que impide cualquier orden. Un grafo dirigido acíclico se abrevia DAG. No confundas orden topológico con ordenar por número de vértice o por grado: esos criterios no garantizan las dependencias.'},
 {title:'Kahn elimina lo que ya puede hacerse',body:'Cuenta el grado de entrada de cada vértice. Los de grado cero no tienen requisitos pendientes y entran a una cola. Al sacar u, lo agregas al orden y eliminas conceptualmente sus aristas: decrementa el grado de cada vecino y encola al que llegue a cero. Si terminas con menos de n vértices, los restantes contienen un ciclo. Para ver por qué un DAG siempre tiene un vértice de grado cero, supone lo contrario y sigue predecesores indefinidamente; como hay finitos vértices, repetirías uno y formarías un ciclo.'},
 {title:'Programación dinámica sobre el orden',body:'Una vez obtenido el orden, puedes contar caminos desde un origen: maneras[origen]=1 y, para cada u, suma maneras[u] a cada vecino v. Todos los predecesores de v se procesan antes que v, así que al usar su valor ya está completo. Para camino más largo usa máximo de distancia[u]+peso(u,v), con menos infinito para inalcanzables. En un DAG puedes manejar pesos negativos porque no hay ciclos que permitan mejorar indefinidamente. En contraste, la misma transición en un orden arbitrario podría propagar un valor antes de recibir todas sus contribuciones.'},
 {title:'Empates y trazas reproducibles',body:'En 0→2,1→2,2→3, la cola inicial contiene 0 y 1. Al retirar 0, el grado de 2 baja de 2 a 1; al retirar 1 baja a cero y se agrega. Sale [0,1,2,3]. Otro orden válido sería [1,0,2,3]. Si el enunciado exige el lexicográficamente menor, cambia la cola por un montículo mínimo para elegir siempre el menor disponible, aumentando el costo a O((n+m) log n). Sin ese requisito, Kahn con cola cuesta O(n+m). Guarda una copia de grados si después necesitas repetir el procedimiento.'},
],{title:'Cuenta caminos con un orden válido',prompt:'En el DAG 0→1,0→2,1→3,2→3,3→4, da un orden topológico y la cantidad de caminos desde 0 a cada vértice. ¿Qué arista añadirías para crear un ciclo?',hints:['Inicializa solamente maneras[0]=1.', 'Una arista de regreso sobre un camino crea un ciclo.'],solution:'Un orden es [0,1,2,3,4]. Las cantidades son [1,1,1,2,2]: 3 recibe una contribución de 1 y otra de 2, y luego envía ambas a 4. Agregar 4→0 crea el ciclo 0→1→3→4→0. En ese nuevo grafo ya no existe un orden topológico. La DP funcionaba porque toda contribución llegaba antes de usar el estado; el ciclo destruye esa garantía.'},{title:'Organizar prerrequisitos',prompt:'Lee n,m y m aristas dirigidas u v, con vértices de 0 a n−1. Ejecuta Kahn usando una cola: encola inicialmente los grados cero en orden numérico, y guarda vecinos en el orden de entrada. Imprime el orden resultante o CICLO si no existe. Límites: 1 ≤ n ≤ 200000; 0 ≤ m ≤ 300000. Este orden de desempate hace única la salida del ejercicio.',hints:['Cada arista eliminada reduce un grado de entrada.', 'Si procesaste menos de n, imprime CICLO.'],solution:'Un vértice entra cuando todos sus predecesores ya salieron, así que toda arista respeta el orden impreso. Si el proceso se detiene, seguir predecesores entre los restantes obliga a encontrar un ciclo. La cola y el orden de adyacencias especificados hacen determinista la respuesta. Tiempo y memoria O(n+m).',tests:[{input:'4 3\n0 2\n1 2\n2 3\n',output:'0 1 2 3\n'},{input:'2 2\n0 1\n1 0\n',output:'CICLO\n'},{input:'1 0\n',output:'0\n'}]});

add('shortest-paths',[
 {title:'Relajar una arista significa mejorar una propuesta',body:'dist[v] es la mejor distancia conocida, inicialmente infinito salvo dist[origen]=0. Al procesar una arista u→v de peso w, la ruta propuesta cuesta dist[u]+w. Si es menor, actualiza dist[v] e inserta la nueva propuesta en el montículo. Relajar no significa que la distancia ya sea definitiva; esa garantía llega al extraer la menor propuesta vigente. Un par (distancia,vértice) permite ordenar por costo y resolver empates por identificador sin cambiar las distancias finales.'},
 {title:'Por qué se puede fijar el menor',body:'Supón que u es el vértice pendiente con menor distancia y existe una ruta más corta que aún no descubrimos. En esa ruta, mira la primera arista que sale de los vértices ya fijados hacia uno pendiente x. Al fijar su predecesor debimos proponer para x una distancia a lo sumo la de la supuesta ruta a u, porque los pesos restantes son no negativos. Entonces x tendría una propuesta menor que u, contradiciendo nuestra elección. Los pesos negativos rompen precisamente esa desigualdad; Dijkstra no los admite aunque algunos ejemplos parezcan funcionar.'},
 {title:'Entradas obsoletas y reconstrucción',body:'Una cola de prioridad estándar no modifica un elemento interno. Cuando mejoras dist[v], insertas otro par y dejas el viejo. Al extraer (d,v), si d!=dist[v], ignóralo: una ruta mejor ya lo reemplazó. Por ejemplo, 0→1 cuesta 10, 0→2 cuesta 2 y 2→1 cuesta 3. Habrá propuestas (10,1) y (5,1); solo la segunda se procesa. Para reconstruir, guarda padre[v]=u en cada mejora. No actualices padre por una propuesta peor ni confundas aristas dirigidas con bidireccionales.'},
 {title:'Escoger según pesos y tamaño',body:'Con montículo y listas, Dijkstra cuesta O((n+m) log n) en un grafo simple, o una cota segura O((n+m) log(n+m)) si hay muchas aristas paralelas. BFS sirve cuando todos los pesos son uno; BFS 0–1 cuando son cero o uno. Bellman–Ford admite negativos y detecta ciclos negativos alcanzables, pero cuesta O(nm). Floyd–Warshall calcula todas las parejas en O(n³), útil para n pequeño. Elige infinito mayor que cualquier ruta válida y evita sumar sobre él. Bajo pesos de hasta mil millones y 200000 vértices, long long es necesario.'},
],{title:'Una arista barata cambia la ruta',prompt:'En un grafo dirigido hay 0→1 de costo 8, 0→2 de costo 2, 2→1 de costo 1 y 1→3 de costo 4. Calcula distancias y explica qué ocurre con la propuesta vieja para 1. ¿Sería correcta una BFS que cuenta aristas?',hints:['La ruta de dos aristas a 1 puede costar menos que la directa.', 'Las distancias son propuestas hasta que se extraen vigentes.'],solution:'Las distancias son [0,3,2,7]. Se propone 8 para 1 desde 0; después, al procesar 2, se mejora a 3. La entrada (8,1) queda obsoleta y se descarta al extraerse. BFS preferiría la arista directa a 1 por tener un paso, pero su costo 8 supera 3. El criterio de procesamiento debe coincidir con la magnitud que se minimiza: costo acumulado en este caso.'},{title:'Rutas con peajes',prompt:'Lee n,m y m aristas dirigidas u v w, con vértices de 0 a n−1 y pesos no negativos. Imprime distancias mínimas desde 0 a todos, usando −1 si son inalcanzables. Límites: 1 ≤ n ≤ 200000; 0 ≤ m ≤ 300000; 0 ≤ w ≤ 1000000000.',hints:['Usa un montículo mínimo de pares distancia,vértice.', 'Descarta una entrada si su distancia ya no coincide con dist[v].'],solution:'Dijkstra fija la menor propuesta vigente. Los pesos no negativos garantizan que ninguna continuación pendiente pueda mejorarla. Relajamos todas las salidas y guardamos propuestas nuevas sin borrar las viejas; la comprobación de vigencia evita trabajo incorrecto. El costo es O((n+m) log(n+m)) y la memoria O(n+m).',tests:[{input:'4 4\n0 1 8\n0 2 2\n2 1 1\n1 3 4\n',output:'0 3 2 7\n'},{input:'2 0\n',output:'0 -1\n'},{input:'3 3\n0 1 0\n1 2 0\n0 2 7\n',output:'0 0 0\n'}]});

add('mst',[
 {title:'Conectar todo no es acercarlo todo al origen',body:'Un árbol de expansión usa todos los vértices y exactamente n−1 aristas, sin ciclos. El mínimo minimiza la suma de pesos de esas aristas, pagadas una vez. No minimiza la suma de distancias desde una sede. En un triángulo con aristas 0−1 de 2,1−2 de 2 y 0−2 de 3, el árbol mínimo usa las dos de 2 y cuesta 4, pero la ruta de 0 a 2 cuesta 4; Dijkstra preferiría la arista directa de 3. Son objetivos diferentes y ambos pueden ser correctos para su propio enunciado.'},
 {title:'La propiedad del corte justifica Kruskal',body:'Un corte separa los vértices en dos grupos no vacíos. La arista más barata que cruza ese corte puede pertenecer a algún árbol mínimo. Para demostrarlo, toma un árbol mínimo que no la incluya; al agregarla aparece un ciclo. Ese ciclo contiene otra arista que cruza el mismo corte y no es más barata. Intercambiarlas mantiene un árbol y no aumenta el peso. Kruskal ordena todas las aristas y agrega una si conecta componentes distintas. El corte de cualquiera de esas componentes permite aplicar la propiedad en cada elección.'},
 {title:'DSU evita ciclos y detecta desconexión',body:'Al procesar una arista u−v, si find(u)==find(v), ya existe un camino en el bosque y añadirla formaría un ciclo: se descarta. Si las raíces difieren, se unen y se agrega su peso. Cuando hay n−1 uniones exitosas, el bosque es un árbol que conecta todo. Si al terminar hay menos, el grafo original está desconectado y no existe árbol de expansión. Pesos negativos no causan problemas: Kruskal solo compara pesos y evita ciclos. Aristas paralelas también se manejan; un lazo nunca une componentes.'},
 {title:'Prim y elecciones equivalentes',body:'Prim empieza desde un vértice y crece un árbol tomando la menor arista que conecta lo alcanzado con lo pendiente. También se apoya en la propiedad del corte y suele implementarse con montículo. Kruskal es cómodo cuando ya tienes una lista de aristas; Prim puede ser útil con vecinos o grafos densos. Los empates pueden producir árboles mínimos distintos con el mismo costo. Kruskal cuesta O(m log m) por ordenar y O(mα(n)) en DSU. La suma de pesos usa 64 bits, incluso cuando cada peso cabe individualmente en int.'},
],{title:'Dos árboles con distintos objetivos',prompt:'En el triángulo con pesos 0−1=2,1−2=2,0−2=3, encuentra el árbol mínimo y un árbol de caminos mínimos desde 0. Compara sus costos de infraestructura y la distancia de 0 a 2.',hints:['Kruskal toma primero las dos aristas de peso 2.', 'Dijkstra necesita preservar la distancia directa de costo 3.'],solution:'El árbol mínimo tiene aristas 0−1 y 1−2, costo total 4 y distancia 0→2 igual a 4. El árbol de caminos mínimos usa 0−1 y 0−2, costo total 5 y distancia a 2 igual a 3. No hay contradicción: uno minimiza infraestructura total y el otro distancias desde el origen. Identificar qué paga el enunciado evita aplicar una técnica correcta al objetivo equivocado.'},{title:'Cablear las sedes',prompt:'Lee n,m y m aristas no dirigidas u v w entre vértices de 0 a n−1. Imprime el costo de un árbol de expansión mínima o IMPOSIBLE si no se pueden conectar todos. Límites: 1 ≤ n ≤ 200000; 0 ≤ m ≤ 300000; |w| ≤ 1000000000.',hints:['Ordena las aristas por peso.', 'Suma únicamente las que unen dos componentes distintas.'],solution:'Kruskal agrega aristas seguras por la propiedad del corte y descarta ciclos con DSU. Si logra n−1 uniones, construyó un árbol mínimo; en caso contrario hay componentes sin conexión posible. El tiempo es O(m log m) y la memoria O(n+m). Un solo vértice necesita cero aristas y cuesta cero.',code:"#include <iostream>\n#include <vector>\n#include <tuple>\n#include <algorithm>\n#include <numeric>\nusing namespace std;\nstruct DSU {\n    vector<int> p, s;\n    DSU(int n) : p(n), s(n, 1) { iota(p.begin(), p.end(), 0); }\n    int f(int x) { return p[x] == x ? x : p[x] = f(p[x]); }\n    bool join(int a, int b) {\n        a = f(a);\n        b = f(b);\n        if (a == b)\n            return false;\n        if (s[a] < s[b])\n            swap(a, b);\n        p[b] = a;\n        s[a] += s[b];\n        return true;\n    }\n};\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<tuple<long long, int, int>> e;\n    while (m--) {\n        int a, b;\n        long long w;\n        cin >> a >> b >> w;\n        e.push_back({w, a, b});\n    }\n    sort(e.begin(), e.end());\n    DSU d(n);\n    long long ans = 0;\n    int used = 0;\n    for (auto [w, a, b] : e)\n        if (d.join(a, b)) {\n            ans += w;\n            used++;\n        }\n    if (used == n - 1)\n        cout << ans << \"\\n\";\n    else\n        cout << \"IMPOSIBLE\\n\";\n}",tests:[{input:'3 3\n0 1 2\n1 2 2\n0 2 3\n',output:'4\n'},{input:'1 0\n',output:'0\n'},{input:'3 1\n0 1 -5\n',output:'IMPOSIBLE\n'}]});

add('intro-sorted-sets',[
 {title:'Orden dinámico, unicidad y multiplicidad',body:'set guarda claves únicas ordenadas; multiset permite repetidas. Ambos mantienen el orden después de insertar y borrar, a diferencia de un vector ordenado donde desplazar datos puede costar O(n). Un set suele implementarse mediante un árbol balanceado, con operaciones de búsqueda e inserción O(log n). Si tienes dos boletos del mismo precio, set perdería la multiplicidad y vendería como si hubiera uno; multiset representa el inventario correcto. Elegir contenedor es decidir qué información importa, no solo qué sintaxis es cómoda.'},
 {title:'Predecesor y sucesor sin cruzar los bordes',body:'s.lower_bound(x) apunta al primer valor ≥x, y s.upper_bound(x) al primero >x. Para encontrar el mayor valor ≤x, toma upper_bound(x) y retrocede una posición, pero solo si no es begin(). Si es begin(), ningún valor sirve. Para encontrar el menor valor ≥x, usa lower_bound y verifica que no sea end() antes de leer. Nunca decrementes begin() ni desreferencies end(): son fronteras, no elementos. El conjunto vacío necesita las mismas comprobaciones y no un valor inventado como sustituto.'},
 {title:'Eliminar una copia y conservar iteradores válidos',body:'En multiset, erase(valor) borra todas las copias iguales; erase(iterador) borra exactamente la señalada. Para vender un boleto a una persona con presupuesto x, encuentra el mayor precio ≤x y borra solo ese iterador. Si hay precios [3,5,5,9] y presupuestos [6,5,4], se venden 5,5,3. El algoritmo satisface cada petición con el boleto más caro que puede pagar, dejando baratos para presupuestos menores. Al borrar, no vuelvas a usar el iterador eliminado. Los demás iteradores del árbol permanecen válidos en estas operaciones.'},
 {title:'Qué consultas no se vuelven rápidas automáticamente',body:'set permite vecinos por valor, pero no tiene acceso aleatorio. Avanzar k posiciones con next o medir distance(begin,it) puede costar O(n). Si necesitas «cuántos valores son menores que x» o «cuál es el k-ésimo», una compresión con Fenwick puede ser apropiada para coordenadas conocidas. Un multiset con dos mitades también permite mantener una mediana deslizante. No dependas de extensiones no estándar del compilador para comenzar: las operaciones ordenadas básicas bastan para muchos problemas y su costo está bien definido.'},
],{title:'Una copia no es todas las copias',prompt:'Tienes multiset {2,4,4,7}. Atiende presupuestos 5,4,1,8 vendiendo el mayor precio que no exceda cada presupuesto. Da las salidas. Explica qué saldría mal al usar erase(4) en la primera venta.',hints:['El primer upper_bound(5) apunta a 7; retrocede.', 'erase por valor elimina todas las coincidencias.'],solution:'Las ventas son 4,4,−1,7 y al final queda el boleto de 2. Con erase(4) en la primera venta desaparecerían ambos boletos de 4; el segundo cliente recibiría 2 y el inventario sería incorrecto. La operación correcta usa el iterador elegido, porque identifica una copia concreta. Si upper_bound devuelve begin(), no existe precio asequible y no se debe retroceder.'},{title:'Boletos para el taller',prompt:'Lee n,q, los n precios y luego q presupuestos. Para cada presupuesto vende y elimina una copia del mayor precio que no lo exceda, o imprime −1 si no existe. Límites: 0 ≤ n ≤ 200000; 1 ≤ q ≤ 200000; 0 ≤ precio,presupuesto ≤ 1000000000.',hints:['Usa multiset y upper_bound.', 'Comprueba begin antes de retroceder; borra por iterador.'],solution:'upper_bound localiza el primer precio demasiado alto; su predecesor, cuando existe, es exactamente el mayor asequible. El multiset conserva copias y orden tras cada venta. Cada consulta e inserción cuesta O(log(n+1)), y la memoria O(n). No se necesita ordenar de nuevo todo el inventario.',code:"#include <iostream>\n#include <set>\nusing namespace std;\nint main() {\n    int n, q;\n    cin >> n >> q;\n    multiset<long long> s;\n    while (n--) {\n        long long x;\n        cin >> x;\n        s.insert(x);\n    }\n    while (q--) {\n        long long x;\n        cin >> x;\n        auto it = s.upper_bound(x);\n        if (it == s.begin())\n            cout << -1 << \"\\n\";\n        else {\n            --it;\n            cout << *it << \"\\n\";\n            s.erase(it);\n        }\n    }\n}",tests:[{input:'4 4\n2 4 4 7\n5 4 1 8\n',output:'4\n4\n-1\n7\n'},{input:'0 2\n0 5\n',output:'-1\n-1\n'},{input:'2 3\n0 0\n0 0 0\n',output:'0\n0\n-1\n'}]});

add('custom-cpp-stl',[
 {title:'Equivalencia depende del comparador',body:'En set, dos objetos se consideran equivalentes si ni comp(a,b) ni comp(b,a) son verdaderos. No depende directamente de operator==. Si comparas estudiantes solo por puntaje, dos estudiantes de igual puntaje se vuelven equivalentes y set conservará solo uno. Para guardar ambos, añade un identificador único como desempate o usa multiset cuando esa equivalencia sea intencional. Para pares, el orden estándar es lexicográfico: primero compara el primer componente y, si empata, el segundo.'},
 {title:'Orden estricto y datos que no deben cambiar',body:'Un comparador debe ser irreflexivo y transitivo; además su noción de equivalencia debe ser coherente. Usar <= falla al comparar un objeto consigo mismo. Comparar por distancia a una variable externa que luego cambia puede invalidar el árbol, porque los elementos quedaron acomodados con otro orden. Si cambia una clave, elimina el elemento bajo su clave anterior y vuelve a insertarlo. En estructuras ordenadas, el criterio no es solo una presentación visual: organiza físicamente las búsquedas y debe permanecer consistente.'},
 {title:'La prioridad del montículo se interpreta al revés',body:'En priority_queue, el elemento superior es el que queda al final según el comparador. Con less<int> sale el mayor; con greater<int> sale el menor. Si quieres sacar mayor puntaje y menor id al empatar, un objeto tiene menor prioridad cuando su puntaje es menor o, al empatar, su id es mayor. Prueba ese comparador con dos objetos concretos antes de generalizarlo. En sort, en cambio, el comparador dice quién aparece primero. Reutilizarlo sin revisar la semántica puede invertir los resultados.'},
 {title:'Separar identidad, orden y presentación',body:'Una estrategia sencilla es representar cada clave de orden por una tupla de datos inmutables. Para menor tiempo y menor id, usa pair<tiempo,id>; para mayor puntaje en set puedes definir explícitamente la comparación descendente. No niegues el valor mínimo de un entero con signo para invertir el orden: su opuesto no cabe. Guarda otros datos asociados por identificador fuera de la clave cuando no participen en ordenar. Diseña pruebas con empate completo, empate parcial y valores extremos; si todos los ejemplos tienen claves distintas, no verificarán el detalle más importante.'},
],{title:'El set que pierde estudiantes',prompt:'Un set compara registros solo por puntaje descendente. Insertas (id=4,puntos=10),(id=2,puntos=10),(id=1,puntos=7). ¿Cuántos conserva? Diseña un orden que conserve los tres y muestre puntos mayores primero, id menor como desempate.',hints:['Equivalente significa que ninguna comparación entre el par es verdadera.', 'El id separa registros con igual puntaje.'],solution:'Conserva dos: los dos de puntaje 10 son equivalentes para ese comparador y la segunda inserción no agrega otro elemento. El comparador correcto primero devuelve a.puntos>b.puntos si difieren; si no, a.id<b.id. El orden resultante es (2,10),(4,10),(1,7). Si dos registros tienen el mismo id y puntos, serán equivalentes intencionalmente. La unicidad del contenedor debe coincidir con la identidad que el problema necesita.'},{title:'Orden del reconocimiento',prompt:'Lee n registros id puntos; todos los ids son distintos. Imprime los ids ordenados por puntos descendentes y, al empatar, id ascendente. Límites: 0 ≤ n ≤ 200000; 1 ≤ id ≤ 1000000000; |puntos| ≤ 1000000000000. Usa un set con comparador explícito para practicar.',hints:['Compara puntos primero y solo después ids.', 'No uses <=; un registro no debe precederse a sí mismo.'],solution:'El comparador define un orden lexicográfico de dos criterios: mayor puntaje y menor identificador. Como los ids son distintos, ningún par de registros se vuelve equivalente y el set conserva todos. Recorrerlo imprime el orden solicitado. La inserción total cuesta O(n log n) y la memoria O(n). sort también sería válido para datos estáticos, pero aquí practicamos la semántica del contenedor.',code:"#include <iostream>\n#include <set>\nusing namespace std;\nstruct R {\n    long long id, p;\n};\nstruct C {\n    bool operator()(const R &a, const R &b) const {\n        if (a.p != b.p)\n            return a.p > b.p;\n        return a.id < b.id;\n    }\n};\nint main() {\n    int n;\n    cin >> n;\n    set<R, C> s;\n    while (n--) {\n        R r;\n        cin >> r.id >> r.p;\n        s.insert(r);\n    }\n    for (auto r : s)\n        cout << r.id << \" \";\n    cout << \"\\n\";\n}",tests:[{input:'3\n4 10\n2 10\n1 7\n',output:'2 4 1\n'},{input:'1\n8 -1000000000000\n',output:'8\n'},{input:'4\n9 3\n3 3\n5 3\n1 4\n',output:'1 3 5 9\n'}]});

add('stacks',[
 {title:'Qué candidato queda dominado',body:'Para cada posición i buscamos el índice anterior más cercano con valor estrictamente menor. Conserva una pila de índices con valores crecientes. Al llegar a[i], cualquier índice j en el tope con a[j]≥a[i] deja de servir para el futuro: i está más cerca de cualquier posición posterior y su valor es igual o menor. Si j pudiera ser menor que un valor futuro, i también lo sería y estaría más cerca. Esta dominancia justifica eliminar j definitivamente; no es una limpieza arbitraria para que la pila «se vea ordenada».'},
 {title:'Una traza con valores iguales',body:'Para [2,5,3,3,1], las respuestas son [−1,0,0,0,−1]. Al llegar al primer 3, retiramos 5 y queda 2. Al llegar al segundo 3, retiramos también el 3 anterior porque buscamos estrictamente menor, no menor o igual. Al llegar 1, retiramos todo. Después de eliminar candidatos inválidos, el tope es el anterior menor más cercano entre los que sobreviven; por dominancia, ninguno de los eliminados podría mejorar esa respuesta. Guarda índices para calcular distancias o responder posiciones.'},
 {title:'Tiempo amortizado y variantes',body:'Un elemento entra a la pila una vez y sale como máximo una vez. Aunque una iteración saque muchos, el total de extracciones no supera n. Por eso el algoritmo cuesta O(n), no O(n²). Para el siguiente menor, puedes recorrer de derecha a izquierda o resolver elementos pendientes cuando aparece un menor. Cambiar estrictamente menor por menor o igual modifica el signo que usas al retirar. Para mayores invierte las comparaciones. Escribe siempre el significado exacto del vecino antes de copiar una plantilla.'},
 {title:'Rectángulos en un histograma',body:'Para cada barra de altura h, el rectángulo más ancho que la usa como altura mínima se extiende hasta antes de una barra estrictamente más baja a cada lado. Si las fronteras son L y R, el ancho es R−L−1 y el área h·ancho. Pilas monótonas calculan esas fronteras en tiempo lineal. Los empates requieren una convención coherente para no perder anchuras; también puedes resolver al retirar barras con una altura centinela cero al final. Una pila por sí sola no demuestra el área: la prueba es que algún rectángulo óptimo tiene una barra mínima que determina su altura.'},
],{title:'La igualdad cambia la respuesta',prompt:'Para [4,4,2,5], da los índices del anterior estrictamente menor y del anterior menor o igual. Explica qué comparación cambia al retirar de la pila.',hints:['En la segunda posición, el 4 anterior sirve solo en una versión.', 'Índices desde cero y −1 cuando no exista.'],solution:'Estrictamente menor: [−1,−1,−1,2]. Menor o igual: [−1,0,−1,2]. Para el primero retiras mientras valor del tope≥actual; para el segundo mientras sea >actual. La diferencia en igualdad refleja la definición del vecino, no una optimización. Un caso con todos los valores iguales detecta rápidamente si implementaste la versión equivocada.'},{title:'Marca anterior más baja',prompt:'Lee n y n valores. Para cada posición imprime el índice anterior más cercano cuyo valor sea estrictamente menor; imprime −1 si no existe. Índices desde cero. Límites: 1 ≤ n ≤ 200000; |valor| ≤ 1000000000000.',hints:['Mantén índices con valores estrictamente crecientes.', 'Retira valores mayores o iguales antes de consultar el tope.'],solution:'Un candidato retirado queda dominado por el actual, que es más reciente y no mayor. Nunca volverá a ser el mejor anterior menor para posiciones futuras. Tras retirar, el tope es el candidato válido más cercano. Cada índice entra y sale a lo sumo una vez, así que el costo es O(n) tiempo y O(n) memoria.',tests:[{input:'5\n2 5 3 3 1\n',output:'-1 0 0 0 -1\n'},{input:'1\n7\n',output:'-1\n'},{input:'4\n4 4 2 5\n',output:'-1 -1 -1 2\n'}]});

add('sliding-window',[
 {title:'Dos razones distintas para sacar elementos',body:'Para el máximo de cada ventana de longitud k, guarda en una deque índices en orden creciente de posición y decreciente de valor. Se elimina por el frente cuando un índice sale de la ventana. Se elimina por atrás cuando llega un valor al menos tan grande: ese nuevo valor está más a la derecha, durará más en ventanas futuras y domina al anterior. No mezcles las dos condiciones. Una se debe al vencimiento de la posición; la otra, a que el candidato dejó de poder ganar.'},
 {title:'Traza con máximos que sobreviven varias ventanas',body:'Para [1,3,2,5,4] y k=3, tras leer 1 la deque contiene su índice 0. Al leer 3, retiramos 0 y queda [1]. Al leer 2 queda [1,2]; la primera respuesta es 3. Al leer 5, retiramos 2 y 1 por atrás y queda [3]; la segunda respuesta es 5. Al leer 4 queda [3,4] y la tercera es 5. El máximo no tiene que salir y volver a entrar para cada ventana: el índice de 5 continúa como candidato mientras siga dentro.'},
 {title:'Por qué el frente siempre responde',body:'Todo elemento de la ventana que ya no está en la deque fue eliminado por otro posterior de valor no menor. Si ese otro también se elimina, existe un reemplazo todavía posterior y al menos tan grande. Por tanto ningún candidato omitido puede superar el máximo de los conservados mientras la cadena de dominancia permanezca dentro de la ventana. Entre los conservados, el orden decreciente de valores coloca al mayor en el frente. Cada índice se inserta una vez y se retira una vez, de donde sale O(n) tiempo amortizado.'},
 {title:'Mínimos, medianas y ventanas variables',body:'Para mínimos, invierte las comparaciones de dominancia. Para máximos y mínimos simultáneos, usa dos deques y puedes mantener condiciones como máximo−mínimo≤K con dos apuntadores. La mediana no es un extremo: descartar un valor porque llegó otro mayor no preserva el elemento central, así que necesita otra estructura, como dos multisets. Guardar valores sin índices dificulta saber cuándo vence una copia entre repetidos. El caso k=1 debe devolver todos los valores y k=n un solo máximo; ambos son pruebas fundamentales.'},
],{title:'Un empate con distinta fecha de vencimiento',prompt:'Para [5,5,1,4] y k=2, da los máximos. Explica por qué puedes retirar el primer 5 cuando llega el segundo si guardas índices y retiras por atrás con <=.',hints:['El segundo 5 es igual de bueno y permanecerá más tiempo.', 'Las ventanas son [5,5],[5,1],[1,4].'],solution:'Los máximos son [5,5,4]. El segundo 5 domina al primero: tiene el mismo valor y una posición posterior, así que cualquier ventana futura que contenga al primero y al segundo puede usarlo, y seguirá disponible más tiempo. Al llegar la última ventana, su índice también vence y se elimina por el frente. La igualdad no perjudica el máximo, pero los índices siguen siendo necesarios para administrar la expiración.'},{title:'Pico de cada bloque de entrenamiento',prompt:'Lee n,k y n valores. Imprime el máximo de cada subarreglo consecutivo de longitud k, de izquierda a derecha. Límites: 1 ≤ k ≤ n ≤ 200000; |valor| ≤ 1000000000000.',hints:['Expulsa índices ≤i−k por el frente.', 'Expulsa valores ≤a[i] por atrás antes de insertar i.'],solution:'La deque conserva candidatos no vencidos y no dominados. Su frente es el máximo actual por el invariante de valores decrecientes. Solo imprimimos al tener k elementos leídos. Cada índice tiene una inserción y a lo sumo una extracción, de modo que el tiempo es O(n), con O(n) memoria en esta implementación que guarda el arreglo.',tests:[{input:'5 3\n1 3 2 5 4\n',output:'3 5 5\n'},{input:'3 1\n-2 8 0\n',output:'-2 8 0\n'},{input:'4 2\n5 5 1 4\n',output:'5 5 4\n'}]});

add('purs',[
 {title:'Qué intervalo guarda cada entrada de Fenwick',body:'Usa índices desde 1. El valor bajo(i)=i&−i es la mayor potencia de dos que divide i. Fenwick[i] guarda la suma del intervalo [i−bajo(i)+1,i]. Por ejemplo, las entradas 1,2,3,4 guardan respectivamente [1,1],[1,2],[3,3],[1,4]. La entrada 6 guarda [5,6] y la 8 guarda [1,8]. Esta definición permite descomponer un prefijo sin traslapes. No intentes interpretar Fenwick[i] como el elemento a[i]; es una suma de bloque que puede abarcar varias posiciones.'},
 {title:'Consultar y actualizar con bits',body:'Para sumar [1,i], agrega Fenwick[i] y retira ese bloque poniendo i-=i&−i. Para i=7 usas bloques [7,7],[5,6],[1,4], que cubren exactamente [1,7]. Para añadir x en una posición i, visita todos los bloques que la contienen mediante i+=i&−i. Por ejemplo actualizar 5 modifica 5,6,8,… Cada salto cambia un bit relevante, por lo que ambas operaciones cuestan O(log n). Una consulta [l,r] se obtiene como prefijo(r)−prefijo(l−1), igual que con prefijos estáticos, pero ahora cada prefijo se calcula dinámicamente.'},
 {title:'Añadir no equivale a asignar',body:'La operación add(i,x) incrementa el elemento, no lo reemplaza. Si el problema pide asignar a[i]=x, guarda el valor previo y actualiza con diferencia x−a[i]; después modifica el arreglo de valores. Con a[i]=7 y nueva asignación 4, debes agregar −3, no 4. El índice cero no es válido para el ciclo de actualización porque i&−i sería cero y el ciclo nunca avanzaría. Convierte índices externos de cero a uno antes de entrar a la estructura.'},
 {title:'Relación con árboles de segmentos',body:'Fenwick es compacto y conveniente para sumas con actualizaciones puntuales. Un árbol de segmentos guarda un árbol binario de intervalos y combina hijos; también permite consultas de mínimo, máximo y otras operaciones asociativas sin necesitar una resta de prefijos. Para n=200000, ambas opciones dan O(log n) por operación. Si las consultas son estáticas, prefijos sencillos ya responden sumas en O(1) y son más fáciles. Si los cambios son por intervalos y las consultas solo puntuales, un Fenwick sobre diferencias adapta la idea; otros modelos necesitan dos Fenwick o propagación diferida.'},
],{title:'Explica los bloques usados',prompt:'En un Fenwick con ocho posiciones, ¿qué entradas cambian al sumar 5 en la posición 3? ¿Qué entradas se suman para consultar el prefijo 7? Si antes a[3]=2 y quieres asignar 9, ¿qué incremento mandas?',hints:['Actualiza sumando el bit bajo.', 'Consulta restando el bit bajo.'],solution:'La actualización visita 3,4,8, cuyos bloques contienen la posición 3. Consultar 7 usa entradas 7,6,4: sus intervalos son [7,7],[5,6],[1,4], disjuntos y completos. Para asignar 9 cuando había 2, agrega 7. Mandar 9 haría que el valor terminara en 11. Estos ejemplos comprueban tanto la representación de bloques como el significado de la operación.'},{title:'Marcador que cambia',prompt:'Lee n,q, el arreglo inicial y q operaciones. «1 i x» suma x a la posición i. «2 l r» pide la suma inclusiva de l a r. Índices desde 1. Imprime solo las consultas. Límites: 1 ≤ n,q ≤ 200000; |valores iniciales|,|incrementos| ≤ 1000000000; todas las posiciones son válidas.',hints:['Construye un Fenwick usando add para cada valor inicial.', 'Una consulta de rango resta dos prefijos.'],solution:'Cada entrada resume su bloque definido por el bit bajo. add actualiza exactamente los bloques que contienen la posición; sum descompone un prefijo en bloques disjuntos. Esto conserva las sumas después de cualquier secuencia de cambios. El costo total es O((n+q) log n) y memoria O(n). long long permite incrementos acumulados grandes.',tests:[{input:'4 4\n1 2 3 4\n2 1 4\n1 2 5\n2 2 3\n2 4 4\n',output:'10\n10\n4\n'},{input:'1 3\n0\n1 1 -7\n2 1 1\n2 1 1\n',output:'-7\n-7\n'},{input:'3 2\n1000000000 1000000000 1000000000\n2 1 3\n2 2 2\n',output:'3000000000\n1000000000\n'}]});

export const goldExpansions = result;

add('dp-trees',[
 {title:'La frontera entre un subárbol y el resto',body:'Al enraizar un árbol, cada subárbol se comunica con el resto solo por la arista hacia su padre. Esa frontera pequeña permite resumir decisiones. Para elegir un conjunto de vértices no adyacentes de peso máximo, basta informar si la raíz del subárbol fue elegida. Define tomar[v] como el óptimo dentro de su subárbol obligando a elegir v, y dejar[v] obligando a excluirlo. La información de cuáles nietos concretos se eligieron no necesita salir del subárbol; solamente su mejor valor compatible con la frontera.'},
 {title:'Derivar las dos transiciones',body:'Si eliges v, ningún hijo puede elegirse: tomar[v]=peso[v]+suma(dejar[hijo]). Si no eliges v, cada hijo puede decidir libremente: dejar[v]=suma(max(tomar[hijo],dejar[hijo])). Los subárboles de hijos distintos no tienen aristas entre sí, por eso sus mejores contribuciones se suman independientemente. Para una hoja, tomar vale su peso y dejar cero. El óptimo total es max(tomar[raíz],dejar[raíz]). Esta independencia fallaría en un grafo con una arista adicional entre dos ramas.'},
 {title:'Ejemplo y una demostración por subárboles',body:'Considera raíz 1 de peso 5 con hijos 2 y 3 de pesos 4 y 4. Las hojas tienen pares (tomar,dejar)=(4,0). En la raíz, tomar=5 y dejar=4+4=8, así que conviene elegir ambos hijos. Si la raíz pesara 10, tomar sería mejor. La demostración es inductiva: las hojas son correctas; suponiendo correctos los hijos, las restricciones con v quedan completamente descritas por sus dos estados. Enumerar tomar o dejar v cubre todas las soluciones válidas y combinar óptimos compatibles no introduce conflictos.'},
 {title:'Orden iterativo y variantes',body:'Construye padres y una lista donde aparezcan antes que sus hijos; procesa al revés para que cada estado hijo esté listo. Así evitas desbordar la pila en una cadena larga. El tiempo es O(n), porque cada arista contribuye una vez a las transiciones, y la memoria O(n). Para contar conjuntos independientes, las sumas de valores se convierten en productos de cantidades entre hijos y sumas entre elecciones. Para escoger exactamente k vértices necesitas una dimensión de cantidad y combinar repartos entre hijos, lo que puede aumentar mucho el costo. El estado depende de qué cruza la frontera, no de que todos los problemas tengan dos opciones.'},
],{title:'Prueba la independencia de ramas',prompt:'En un árbol con aristas 1−2,1−3,3−4 y pesos [5,4,3,6], calcula tomar y dejar para cada vértice y un conjunto óptimo. ¿Qué falla si agregamos la arista 2−4?',hints:['Procesa hojas 2 y 4 primero.', 'Agregar 2−4 conecta ramas que la recurrencia trataba como independientes.'],solution:'Para 2: (4,0); para 4: (6,0). Para 3: tomar=3 y dejar=6. Para 1: tomar=5+0+6=11; dejar=4+max(3,6)=10. El óptimo elige {1,4}, valor 11. Si agregas 2−4, las ramas bajo 1 ya pueden entrar en conflicto; la combinación que da dejar[1]=4+6 elegiría dos vecinos y sería inválida. El grafo dejó de ser un árbol y esa independencia desapareció.'},{title:'Representantes sin vecinos',prompt:'Lee n, n pesos no negativos y n−1 aristas de un árbol con vértices de 1 a n. Elige vértices sin que dos elegidos compartan una arista. Imprime la mayor suma de pesos. Límites: 1 ≤ n ≤ 200000; 0 ≤ peso ≤ 1000000000.',hints:['Guarda dos estados: elegir o excluir la raíz del subárbol.', 'Procesa hijos antes que padres, preferentemente con orden iterativo.'],solution:'Las dos transiciones consideran la única restricción que cruza cada arista padre-hijo. Al elegir el padre forzamos excluir al hijo; al excluirlo permitimos ambas opciones. Los subárboles son independientes y sus valores se suman. Un recorrido inverso evalúa todos los estados en O(n) tiempo y memoria sin recursión profunda.',code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nint main() {\n    int n;\n    cin >> n;\n    vector<long long> take(n), skip(n);\n    for (auto &x : take)\n        cin >> x;\n    vector<vector<int>> g(n);\n    for (int i = 1; i < n; i++) {\n        int a, b;\n        cin >> a >> b;\n        --a;\n        --b;\n        g[a].push_back(b);\n        g[b].push_back(a);\n    }\n    vector<int> p(n, -1), o{0};\n    for (int i = 0; i < n; i++) {\n        int v = o[i];\n        for (int u : g[v])\n            if (u != p[v]) {\n                p[u] = v;\n                o.push_back(u);\n            }\n    }\n    for (int i = n - 1; i > 0; i--) {\n        int v = o[i];\n        take[p[v]] += skip[v];\n        skip[p[v]] += max(take[v], skip[v]);\n    }\n    cout << max(take[0], skip[0]) << \"\\n\";\n}",tests:[{input:'4\n5 4 3 6\n1 2\n1 3\n3 4\n',output:'11\n'},{input:'1\n0\n',output:'0\n'},{input:'3\n5 4 4\n1 2\n1 3\n',output:'8\n'}]});

add('all-roots',[
 {title:'Calcular todas las raíces sin repetir todo',body:'Queremos suma[v], la suma de distancias desde v a todos los vértices de un árbol sin pesos. Ejecutar un recorrido desde cada v cuesta O(n²). Enraiza primero en 0 y calcula profundidad de cada vértice; su suma da suma[0]. Calcula también tamaño[v], la cantidad de vértices en el subárbol de v. Esos tamaños permiten describir exactamente qué distancias cambian al mover la raíz por una arista. No hay que reconstruir el árbol: la nueva respuesta sale de corregir la anterior.'},
 {title:'Derivar la fórmula de una arista',body:'Al pasar de padre p a hijo h, los tamaño[h] vértices dentro del subárbol de h quedan un paso más cerca. Los otros n−tamaño[h] quedan un paso más lejos. Entonces suma[h]=suma[p]−tamaño[h]+(n−tamaño[h])=suma[p]+n−2·tamaño[h]. Los dos grupos son disjuntos y cubren todo el árbol, incluido h y p. Para aristas con peso w, el cambio se multiplica por w. Si los vértices tienen pesos de importancia, reemplaza cantidades por sumas de pesos de cada grupo.'},
 {title:'Dos pasadas y una traza',body:'En la cadena 0−1−2−3, con raíz 0, tamaños=[4,3,2,1] y suma[0]=0+1+2+3=6. La fórmula da suma[1]=6+4−6=4, suma[2]=4+4−4=4 y suma[3]=4+4−2=6. La primera pasada calcula tamaños de abajo hacia arriba y la respuesta inicial; la segunda propaga respuestas de padres a hijos. Procesar la segunda al revés sería incorrecto porque todavía no tendrías la respuesta del padre. Ambas pasadas recorren O(n) aristas.'},
 {title:'El patrón general de contribuciones',body:'En otros problemas, cada vecino aporta un resumen a v y quieres calcular lo que v enviaría a ese vecino excluyendo su propia contribución. Si la operación tiene inversa, a veces puedes restar. Para máximo o para productos con ceros, restar o dividir no sirve; prefijos y sufijos de contribuciones permiten combinar todos menos uno en O(1) después de O(grado) preparación. Así la suma de trabajo sobre todos los grados sigue siendo O(n). Reenraizar es una organización de estados por arista dirigida; la fórmula concreta debe derivarse para cada objetivo.'},
],{title:'Cuánto cambia al cruzar una arista',prompt:'Un árbol tiene 10 vértices y una arista padre-hijo cuyo subárbol hijo contiene 7. Si la suma de distancias desde el padre es 25, ¿cuánto vale desde el hijo? Explica por qué la suma disminuye. ¿Y si la arista pesara 3?',hints:['Siete vértices se acercan y tres se alejan.', 'Con peso 3 cada cambio individual tiene magnitud 3.'],solution:'Sin pesos, la nueva suma es 25−7+3=21. Disminuye porque movemos la raíz hacia el grupo más grande: se benefician siete distancias y solo empeoran tres. Con arista de peso 3 y suma inicial 25, el cambio sería 3·(3−7)=−12 y la suma nueva 13. La fórmula ponderada supone que las distancias iniciales ya se midieron con esos pesos.'},{title:'Sede más cercana a todos',prompt:'Lee n y n−1 aristas de un árbol no dirigido con vértices de 1 a n. Imprime para cada vértice la suma de distancias en aristas a todos los demás. Límites: 1 ≤ n ≤ 200000.',hints:['Calcula la suma de profundidades desde 1 y todos los tamaños.', 'Propaga respuesta[h]=respuesta[p]+n−2·tamaño[h].'],solution:'Una pasada obtiene profundidades, padres y tamaños. La suma de profundidades es la respuesta de la raíz. Después cruzamos cada arista hacia sus hijos: los del subárbol se acercan uno y todos los demás se alejan uno. Esta partición demuestra la fórmula. Tiempo y memoria O(n), con long long porque una cadena produce sumas cuadráticas en n.',code:"#include <iostream>\n#include <vector>\nusing namespace std;\nint main() {\n    int n;\n    cin >> n;\n    vector<vector<int>> g(n);\n    for (int i = 1; i < n; i++) {\n        int a, b;\n        cin >> a >> b;\n        --a;\n        --b;\n        g[a].push_back(b);\n        g[b].push_back(a);\n    }\n    vector<int> p(n, -1), dep(n), sz(n, 1), o{0};\n    for (int i = 0; i < n; i++) {\n        int v = o[i];\n        for (int u : g[v])\n            if (u != p[v]) {\n                p[u] = v;\n                dep[u] = dep[v] + 1;\n                o.push_back(u);\n            }\n    }\n    vector<long long> ans(n);\n    for (int x : dep)\n        ans[0] += x;\n    for (int i = n - 1; i > 0; i--)\n        sz[p[o[i]]] += sz[o[i]];\n    for (int i = 1; i < n; i++) {\n        int v = o[i];\n        ans[v] = ans[p[v]] + n - 2LL * sz[v];\n    }\n    for (auto x : ans)\n        cout << x << \" \";\n    cout << \"\\n\";\n}",tests:[{input:'4\n1 2\n2 3\n3 4\n',output:'6 4 4 6\n'},{input:'1\n',output:'0\n'},{input:'4\n1 2\n1 3\n1 4\n',output:'3 5 5 5\n'}]});

add('tree-euler',[
 {title:'DFS coloca cada subárbol en un bloque',body:'Al entrar a v en DFS, asigna tin[v]=contador y aumenta contador. Termina de explorar todos sus descendientes antes de regresar al padre; justo al salir guarda tout[v]=contador. Ningún vértice exterior se visita entre esas dos marcas. Por ello el subárbol de v corresponde al intervalo semiabierto [tin[v],tout[v]). El tamaño es tout[v]−tin[v]. Esta propiedad depende de profundidad primero: una lista BFS pone juntos los niveles, pero puede intercalar descendientes de padres distintos y no sirve para el mismo aplanamiento.'},
 {title:'Ejemplo con valores y consultas',body:'Para aristas 1−2,1−3,3−4,3−5, una DFS puede producir orden [1,2,3,4,5]. Las entradas son [0,1,2,3,4] y las salidas [5,2,5,4,5]. El subárbol de 3 ocupa [2,5), es decir los vértices 3,4,5. Si sus valores originales son [10,20,30,40,50], el arreglo plano tiene esos valores y la suma del subárbol de 3 es 120. Con otro orden de hijos, el bloque cambia de posición pero sigue siendo contiguo; no es necesario imponer un orden numérico.'},
 {title:'Trasladar operaciones del árbol a un arreglo',body:'Una asignación al valor de v se vuelve una actualización puntual en tin[v]. Una suma de subárbol se vuelve una suma de rango. Puedes usar prefijos si los valores son estáticos, Fenwick si hay incrementos puntuales, o un árbol de segmentos para mínimos y máximos. También puedes comprobar ancestros: u es ancestro de v, incluyéndose a sí mismo, si tin[u]≤tin[v]<tout[u]. No confundas esa prueba con adyacencia; un ancestro puede estar muchas aristas arriba.'},
 {title:'Dos recorridos llamados Euler',body:'Para aplanar subárboles registramos cada vértice una vez al entrar. Para LCA mediante mínimo de profundidad se usa otro registro: anotar un vértice al entrar y volver a anotarlo cada vez que regresas de un hijo. Ese recorrido tiene longitud 2n−1 y preserva subidas y bajadas. No mezcles first de ese recorrido con tin del arreglo de subárboles sin explicar qué representan. En implementaciones iterativas puedes usar eventos de entrada y salida, o calcular tamaños después de obtener una verdadera lista DFS; entonces tout=tin+tamaño.'},
],{title:'Una lista por niveles no basta',prompt:'En el árbol con aristas 1−2,1−3,2−4,3−5, compara el orden BFS [1,2,3,4,5] con DFS [1,2,4,3,5]. ¿En cuál es contiguo el subárbol de 2? Da su intervalo usando índices desde cero.',hints:['El subárbol de 2 es {2,4}.', 'DFS termina una rama antes de comenzar la otra.'],solution:'En BFS, 2 está en posición 1 y 4 en 3; la posición 2 contiene el vértice 3, que no pertenece al subárbol. No existe un intervalo que contenga exactamente {2,4}. En DFS ocupan posiciones 1 y 2, intervalo [1,3). El subárbol de 3 ocupa [3,5). La contigüidad se prueba por cómo DFS completa cada rama, no por cualquier orden donde los padres aparezcan primero.'},{title:'Recursos de cada subárbol',prompt:'Lee n,q, n valores, n−1 aristas de un árbol y q vértices consultados. Enraíza en 1 y, para cada consulta v, imprime la suma de valores de su subárbol incluyéndolo. Límites: 1 ≤ n,q ≤ 200000; |valor| ≤ 1000000000. Vértices de 1 a n; no hay actualizaciones.',hints:['Obtén un orden DFS, no BFS.', 'Calcula tamaños y prefijos del arreglo aplanado.'],solution:'La pila produce un orden DFS de entrada. Cada subárbol ocupa tin[v] hasta tin[v]+tamaño[v]−1. Una pasada inversa calcula tamaños y los prefijos de valores responden cada consulta por resta. Como los valores no cambian, no necesitamos Fenwick. Tiempo O(n+q), memoria O(n), y recorrido iterativo para cadenas profundas.',code:"#include <iostream>\n#include <vector>\nusing namespace std;\nint main() {\n    int n, q;\n    cin >> n >> q;\n    vector<long long> a(n);\n    for (auto &x : a)\n        cin >> x;\n    vector<vector<int>> g(n);\n    for (int i = 1; i < n; i++) {\n        int u, v;\n        cin >> u >> v;\n        --u;\n        --v;\n        g[u].push_back(v);\n        g[v].push_back(u);\n    }\n    vector<int> p(n, -1), tin(n), sz(n, 1), st{0}, o;\n    while (!st.empty()) {\n        int v = st.back();\n        st.pop_back();\n        tin[v] = o.size();\n        o.push_back(v);\n        for (int u : g[v])\n            if (u != p[v]) {\n                p[u] = v;\n                st.push_back(u);\n            }\n    }\n    for (int i = n - 1; i > 0; i--)\n        sz[p[o[i]]] += sz[o[i]];\n    vector<long long> pref(n + 1);\n    for (int i = 0; i < n; i++)\n        pref[i + 1] = pref[i] + a[o[i]];\n    while (q--) {\n        int v;\n        cin >> v;\n        --v;\n        cout << pref[tin[v] + sz[v]] - pref[tin[v]] << \"\\n\";\n    }\n}",tests:[{input:'5 3\n10 20 30 40 50\n1 2\n1 3\n3 4\n3 5\n3\n1\n2\n',output:'120\n150\n20\n'},{input:'1 1\n-7\n1\n',output:'-7\n'},{input:'5 2\n1 2 3 4 5\n1 2\n1 3\n2 4\n3 5\n2\n3\n',output:'6\n8\n'}]});

add('lca-euler',[
 {title:'Definir el ancestro común más bajo',body:'En un árbol con raíz, un ancestro de v es cualquier vértice del camino entre la raíz y v, incluyendo ambos extremos. LCA(u,v) es el ancestro compartido de mayor profundidad. Existe y es único porque ambos caminos parten de la raíz y comparten un prefijo. Si u es ancestro de v, la respuesta es u; si son iguales, es ese mismo vértice. Con raíz 1 y aristas 1−2,1−3,3−4,3−5, LCA(4,5)=3 y LCA(2,4)=1.'},
 {title:'El recorrido que vuelve a anotar padres',body:'Registra el vértice actual al entrar y cada vez que regresas desde un hijo. En el ejemplo, visitando 2 antes de 3 y 4 antes de 5, Euler=[1,2,1,3,4,3,5,3,1], con profundidades [0,1,0,1,2,1,2,1,0]. Guarda la primera aparición de cada vértice. Entre first[u] y first[v], el vértice de menor profundidad es LCA(u,v): para viajar entre las dos ramas DFS debe pasar por su unión, y no sale por encima de ella antes de visitar el otro extremo. Esta reducción convierte LCA en mínimo de rango.'},
 {title:'Responder mínimos con tabla dispersa',body:'Una tabla dispersa guarda el mínimo de cada bloque de longitud potencia de dos. st[k][i] combina st[k−1][i] y st[k−1][i+2^(k−1)]. Para una consulta inclusiva [l,r], sea k=floor(log2(r−l+1)). Compara los bloques que empiezan en l y terminan en r, ambos de longitud 2^k. Pueden traslaparse porque mínimo es idempotente: repetir un elemento no cambia el mínimo. Guarda el índice o vértice del mínimo, no solo su profundidad. Preprocesa O(n log n), responde O(1) y usa O(n log n) memoria.'},
 {title:'Distancias, cambios de raíz y alternativas',body:'Una vez conocido w=LCA(u,v), distancia(u,v)=profundidad[u]+profundidad[v]−2·profundidad[w]. Para pesos, usa distancia acumulada a la raíz en la misma fórmula. El preprocesamiento depende de una raíz elegida y de un árbol estático; cambiar aristas requiere otro modelo. También existe levantamiento binario, que guarda ancestros a potencias de dos y responde LCA en O(log n). Para practicar la reducción Euler puedes empezar con un árbol de segmentos de mínimos: usa O(n) memoria y consultas O(log n), y es la versión ejecutable de esta lección.'},
],{title:'Localiza el mínimo correcto',prompt:'Con Euler=[1,2,1,3,4,3,5,3,1], usa primeras apariciones para encontrar LCA(4,5), LCA(2,5) y distancia(2,4). Explica por qué el arreglo DFS de una sola aparición no basta para esta misma consulta de mínimos.',hints:['first[4]=4 y first[5]=6.', 'La profundidad mínima entre las apariciones identifica la unión.'],solution:'Entre posiciones 4 y 6 aparecen [4,3,5], de profundidades [2,1,2], así que LCA(4,5)=3. Entre posiciones 1 y 6 aparece la raíz 1, por tanto LCA(2,5)=1. La distancia de 2 a 4 es 1+2−2·0=3. En el orden simple [1,2,3,4,5], el intervalo entre 4 y 5 no incluye a 3; omitir retornos pierde la información necesaria para este mínimo.'},{title:'Punto de reunión en el árbol',prompt:'Lee n,q, n−1 aristas de un árbol con vértices de 1 a n y q pares u,v. Con raíz 1, imprime LCA(u,v) para cada par. Límites: 1 ≤ n,q ≤ 100000. Usa recorrido Euler completo y mínimos de profundidad.',hints:['Anota al padre al regresar de cada hijo.', 'Guarda primeras apariciones y consulta el mínimo entre ellas.'],solution:'Un recorrido iterativo con posición del siguiente vecino simula entradas y retornos de DFS sin recursión. Construimos un árbol de segmentos donde cada nodo guarda el vértice de menor profundidad. La propiedad del recorrido Euler garantiza que el mínimo entre primeras apariciones es el ancestro común más bajo. Construcción O(n), cada consulta O(log n) y memoria O(n).',code:"#include <iostream>\n#include <vector>\n#include <algorithm>\nusing namespace std;\nint main() {\n    int n, q;\n    cin >> n >> q;\n    vector<vector<int>> g(n);\n    for (int i = 1; i < n; i++) {\n        int a, b;\n        cin >> a >> b;\n        --a;\n        --b;\n        g[a].push_back(b);\n        g[b].push_back(a);\n    }\n    vector<int> p(n, -1), dep(n), first(n, -1), next(n), st{0}, e;\n    first[0] = 0;\n    e.push_back(0);\n    while (!st.empty()) {\n        int v = st.back();\n        if (next[v] == (int)g[v].size()) {\n            st.pop_back();\n            if (!st.empty())\n                e.push_back(st.back());\n        } else {\n            int u = g[v][next[v]++];\n            if (u == p[v])\n                continue;\n            p[u] = v;\n            dep[u] = dep[v] + 1;\n            first[u] = e.size();\n            e.push_back(u);\n            st.push_back(u);\n        }\n    }\n    auto best = [&](int a, int b) {\n        if (a == -1)\n            return b;\n        if (b == -1)\n            return a;\n        return dep[a] < dep[b] ? a : b;\n    };\n    int z = 1;\n    while (z < (int)e.size())\n        z *= 2;\n    vector<int> seg(2 * z, -1);\n    for (int i = 0; i < (int)e.size(); i++)\n        seg[z + i] = e[i];\n    for (int i = z - 1; i; i--)\n        seg[i] = best(seg[2 * i], seg[2 * i + 1]);\n    while (q--) {\n        int a, b;\n        cin >> a >> b;\n        int l = first[a - 1], r = first[b - 1];\n        if (l > r)\n            swap(l, r);\n        l += z;\n        r += z + 1;\n        int ans = -1;\n        while (l < r) {\n            if (l & 1)\n                ans = best(ans, seg[l++]);\n            if (r & 1)\n                ans = best(ans, seg[--r]);\n            l /= 2;\n            r /= 2;\n        }\n        cout << ans + 1 << \"\\n\";\n    }\n}",tests:[{input:'5 3\n1 2\n1 3\n3 4\n3 5\n4 5\n2 4\n3 3\n',output:'3\n1\n3\n'},{input:'1 1\n1 1\n',output:'1\n'},{input:'4 2\n1 2\n2 3\n3 4\n2 4\n1 4\n',output:'2\n1\n'}]});

add('ternary-search',[
 {title:'La forma de la función es la hipótesis central',body:'Una función unimodal de mínimo primero decrece y después crece; puede tener un tramo plano de mínimos si el algoritmo trata los empates correctamente. No tiene varios valles separados. Para aplicar búsqueda ternaria necesitas justificar esa forma a partir del problema, no solo verla en algunos valores. La función f(x)=(x−4)²+7 tiene mínimo en 4; una suma de cuadrados también es convexa y, por ello, unimodal. Una función con oscilaciones o varios mínimos locales puede engañar cualquier descarte de tercios.'},
 {title:'Qué tercio podemos descartar',body:'Elige m1 y m2 dentro de [l,r], con m1<m2. Si f(m1)<f(m2), el mínimo no está a la derecha de m2: una función que aún descendiera hasta allí no podría haber subido entre m1 y m2. Conserva la parte izquierda. Si f(m1)>f(m2), descarta la parte anterior a m1. Para funciones estrictamente convexas, la igualdad permite conservar la región central; con mesetas hay que cuidar la formulación exacta de unimodalidad. Cada paso reduce el intervalo por un factor constante, dando O(log ancho) evaluaciones en el caso entero.'},
 {title:'Enteros y reales necesitan terminaciones distintas',body:'En enteros, m1 y m2 pueden coincidir cuando quedan pocas posiciones. Detén la búsqueda al quedar tres o cuatro candidatos y evalúalos todos. En reales, usa una cantidad fija de iteraciones suficiente para la precisión requerida y conserva un intervalo; no compares flotantes por igualdad exacta como criterio de terminación. El resultado puede necesitar imprimir varias cifras decimales. Si la función se evalúa en O(n), ese factor multiplica el costo de todas las iteraciones. No confundas el número de consultas a la función con el tiempo total.'},
 {title:'A veces hay una solución más directa',body:'Para minimizar suma de (x−a[i])², expandir da n·x²−2x·suma(a)+suma(a²). El mínimo real está en el promedio; el mínimo entero se encuentra entre piso y techo de ese promedio. La búsqueda ternaria también funciona y sirve para practicar, pero la fórmula evita iteraciones. Para suma de distancias absolutas, una mediana minimiza. Otra opción en funciones discretas convexas es buscar binariamente el primer x donde f(x+1)−f(x)≥0. Reconocer estructura algebraica puede simplificar el problema más que aplicar una técnica general.'},
],{title:'Una hipótesis que no puedes omitir',prompt:'Explica por qué la función definida por valores [0,8,7,6,5,4,3,2,1] en x=0,…,8 no cumple la forma de un único valle de mínimo. Para f(x)=(x−2)²+(x−5)², encuentra el mínimo entre enteros y sus posiciones.',hints:['La primera función empieza subiendo y después baja.', 'El promedio de 2 y 5 es 3.5.'],solution:'La primera función tiene un mínimo en el extremo 0 y luego otra región decreciente; no es primero decreciente y después creciente. Un descarte apoyado en esa hipótesis puede perder x=0. En la segunda función, los enteros más cercanos al promedio son 3 y 4; ambos dan 1+4=5. El mínimo entero puede aparecer en dos posiciones adyacentes aunque la función real tenga un único mínimo. Por eso el ejercicio pide el valor y no un desempate de posición.'},{title:'Ubicación equilibrada',prompt:'Lee n y n coordenadas enteras. Escoge un entero x que minimice la suma de (x−a[i])² e imprime ese costo mínimo. Límites: 1 ≤ n ≤ 200000; |a[i]| ≤ 1000000. Implementa búsqueda ternaria entera para practicar; los óptimos están entre el mínimo y máximo de las coordenadas.',hints:['La suma de cuadrados es estrictamente convexa.', 'Cuando queden pocas posiciones, evalúa todas.'],solution:'Cada término es convexo y su suma tiene un único mínimo real, así que las comparaciones de tercios permiten descartar regiones sin óptimo. El intervalo entero inicial contiene cualquier óptimo: salir del rango de datos aumenta todas las distancias. Al quedar a lo sumo cuatro candidatos calculamos el menor costo exacto. Tiempo O(n log rango), memoria O(n); long long guarda cuadrados y suma.',code:"#include <iostream>\n#include <vector>\n#include <algorithm>\n#include <limits>\nusing namespace std;\nint main() {\n    int n;\n    cin >> n;\n    vector<long long> a(n);\n    for (auto &x : a)\n        cin >> x;\n    long long l = *min_element(a.begin(), a.end()), r = *max_element(a.begin(), a.end());\n    auto f = [&](long long x) {\n        long long s = 0;\n        for (auto y : a) {\n            long long d = x - y;\n            s += d * d;\n        }\n        return s;\n    };\n    while (r - l > 3) {\n        long long u = l + (r - l) / 3, v = r - (r - l) / 3;\n        if (f(u) <= f(v))\n            r = v;\n        else\n            l = u;\n    }\n    long long ans = numeric_limits<long long>::max();\n    for (long long x = l; x <= r; x++)\n        ans = min(ans, f(x));\n    cout << ans << \"\\n\";\n}",tests:[{input:'2\n2 5\n',output:'5\n'},{input:'1\n-1000000\n',output:'0\n'},{input:'3\n-2 0 2\n',output:'8\n'}]});

add('hashing',[
 {title:'Una huella tiene menos información que la cadena',body:'Una función hash transforma una cadena en un número pequeño. Si dos cadenas tienen hashes distintos, seguro son diferentes. Si sus hashes coinciden, pueden ser iguales o haber colisionado. Como hay más cadenas posibles que residuos, las colisiones son inevitables para alguna pareja. El beneficio es comparar muchas propuestas rápidamente; el precio es controlar y reconocer esa posibilidad. No presentes un algoritmo probabilístico como una demostración de igualdad exacta. Si el enunciado o aplicación exige certeza, verifica caracteres o usa una técnica exacta apropiada.'},
 {title:'Construcción polinomial con una orientación fija',body:'Representa a=1,b=2,…,z=26 y define H[0]=0, H[i+1]=(H[i]·B+valor(s[i]))%M. Para aba con B=31, el hash sin reducir es 1·31²+2·31+1=1024. Precalcula potencias P[0]=1 y P[i+1]=P[i]·B%M. El hash de [l,r) es H[r]−H[l]·P[r−l], normalizado módulo M. Multiplicar el prefijo por la potencia correcta alinea sus posiciones y cancela exactamente los caracteres anteriores; esta orientación no necesita inversos modulares.'},
 {title:'Longitudes, normalización y colisiones',body:'Al comparar cadenas, compara también sus longitudes. Usa valores positivos para letras y una base mayor que el alfabeto como elección práctica, pero eso por sí solo no elimina colisiones. Un módulo primo grande ayuda al análisis cuando la base se elige aleatoriamente; dos módulos reducen la probabilidad de colisión bajo supuestos adecuados, sin convertirla en cero. Con módulo 7 y base 3, a y h tienen el mismo valor residual si h=8: es un ejemplo pequeño de pérdida de información. Después de restar, suma M antes de aplicar % para evitar residuos negativos.'},
 {title:'Aplicaciones y alternativas exactas',body:'Puedes agrupar substrings por hash, comparar un patrón con todas las ventanas de su longitud o buscar el primer carácter distinto usando hashes y búsqueda binaria. Cada consulta de hash cuesta O(1) después de O(n) preparación, pero verificar caracteres puede agregar costo lineal en la longitud. Para buscar todas las apariciones de un único patrón, KMP o Z dan una solución exacta lineal; para muchas comparaciones de sufijos existen estructuras específicas. El ejercicio de esta página pide el valor de la huella, por lo que su respuesta numérica es exacta y no afirma igualdad de cadenas.'},
],{title:'Qué puedes concluir con certeza',prompt:'Dos cadenas de la misma longitud dan hashes distintos; otras dos dan hashes iguales. ¿Qué concluyes en cada caso? Con base 31 y sin reducir todavía, calcula los hashes de aba y bab usando a=1,b=2.',hints:['Una función da siempre el mismo resultado para la misma entrada.', 'Evalúa como ((primera·31)+segunda)·31+tercera.'],solution:'Hashes distintos prueban que las cadenas son distintas: entradas iguales siempre producen el mismo valor. Hashes iguales no prueban igualdad porque puede haber colisión. aba da (1·31+2)·31+1=1024; bab da (2·31+1)·31+2=1955. Si una igualdad de hash debe justificar una decisión exacta, compara además las cadenas o utiliza un algoritmo que no dependa de ausencia de colisiones.'},{title:'Huellas de fragmentos',prompt:'Lee una cadena s de letras a–z, luego q y q pares l,r. Para cada substring [l,r), imprime su hash polinomial con base 31, módulo 1000000007 y valores a=1,…,z=26, colocando el primer carácter en la potencia más alta. Índices desde 0; el fragmento vacío tiene hash cero. Límites: 1 ≤ |s|,q ≤ 200000; 0 ≤ l ≤ r ≤ |s|.',hints:['Construye prefijos H y potencias de 31.', 'Resta H[l] multiplicado por 31 elevado a r−l.'],solution:'El prefijo H[r] contiene el fragmento deseado y el prefijo anterior desplazado r−l potencias. Restar H[l]·P[r−l] lo elimina. Normalizamos el residuo y respondemos en O(1). Preparación O(n), memoria O(n), consultas totales O(q). La tarea calcula huellas; no asume que huellas iguales impliquen cadenas iguales.',code:"#include <iostream>\n#include <vector>\n#include <string>\nusing namespace std;\nint main() {\n    string s;\n    cin >> s;\n    const long long M = 1000000007;\n    int n = s.size();\n    vector<long long> h(n + 1), p(n + 1, 1);\n    for (int i = 0; i < n; i++) {\n        h[i + 1] = (h[i] * 31 + s[i] - 'a' + 1) % M;\n        p[i + 1] = p[i] * 31 % M;\n    }\n    int q;\n    cin >> q;\n    while (q--) {\n        int l, r;\n        cin >> l >> r;\n        cout << (h[r] - h[l] * p[r - l] % M + M) % M << \"\\n\";\n    }\n}",tests:[{input:'ababa\n3\n0 3\n2 5\n1 4\n',output:'1024\n1024\n1955\n'},{input:'z\n2\n0 1\n0 0\n',output:'26\n0\n'},{input:'abc\n2\n0 3\n1 3\n',output:'1026\n65\n'}]});

add('hashmaps',[
 {title:'Una clave no necesita ser un índice pequeño',body:'unordered_map relaciona claves con valores usando una función hash para elegir una cubeta. Permite guardar frecuencias de enteros grandes, cadenas o estados sin reservar un arreglo hasta el mayor valor. Dos claves distintas pueden caer en la misma cubeta: el contenedor compara las claves completas para distinguirlas, así que esas colisiones afectan rendimiento, no exactitud. Esto es distinto de comparar solo hashes de cadenas. map, por su parte, mantiene claves ordenadas y ofrece O(log n) garantizado por operación.'},
 {title:'Derivar la ecuación de prefijos',body:'Un subarreglo [l,r) suma K exactamente cuando P[r]−P[l]=K, equivalente a P[l]=P[r]−K. Al recorrer el extremo derecho r, basta saber cuántos prefijos anteriores tienen ese valor. Inicializa frecuencia[0]=1 para representar el prefijo vacío. Primero agrega frecuencia[P[r]−K] a la respuesta y después registra P[r]. El orden es indispensable: si registras primero y K=0, contarías también el intervalo vacío [r,r), que el ejercicio no permite.'},
 {title:'Traza con números negativos',body:'Para [1,−1,1] y K=1, comienza con frecuencia{0:1}. El primer prefijo es 1: busca 0 y agrega una respuesta, luego registra 1. El siguiente es 0: busca −1, no hay; registra otra copia de 0. El último es 1: busca 0 y encuentra dos, por lo que agrega dos. Total tres subarreglos: el primer [1], el último [1] y el arreglo completo. Los negativos no perjudican la ecuación; a diferencia de dos apuntadores, no necesitamos monotonía de las sumas.'},
 {title:'Costos, inserciones accidentales y alternativas',body:'operator[] inserta una clave con valor cero si no existe. Eso es útil al incrementar una frecuencia, pero para una consulta que no debe modificar usa find. reserve puede reducir realojamientos cuando conoces cuántas claves habrá. unordered_map ofrece O(1) esperado por operación, pero su peor caso puede ser lineal por colisiones; el algoritmo completo puede degradarse a O(n²). Si necesitas una garantía determinista, map da O(n log n), o comprime todas las sumas prefijas y usa un arreglo de frecuencias. La respuesta puede ser n(n+1)/2, así que usa long long.'},
],{title:'El prefijo vacío también cuenta',prompt:'Cuenta subarreglos no vacíos de [0,0,0] con suma cero. Explica cómo las frecuencias del prefijo cero pasan por 1,2,3,4 y qué error produce insertar el prefijo actual antes de consultar.',hints:['Cada subarreglo suma cero.', 'En el paso r hay r prefijos anteriores disponibles.'],solution:'Las contribuciones son 1,2,3, total 6. La frecuencia empieza en 1 por el prefijo anterior al primer elemento y aumenta después de cada consulta. Insertar antes produciría contribuciones 2,3,4, total 9: tres de ellas serían intervalos vacíos, uno por posición procesada. El orden de actualización representa la condición l<r y es parte de la prueba, no un detalle intercambiable.'},{title:'Bloques de balance exacto',prompt:'Lee n,K y n enteros, que pueden ser negativos. Imprime cuántos subarreglos no vacíos suman exactamente K. Límites: 1 ≤ n ≤ 200000; |K| ≤ 100000000000000; |a[i]| ≤ 1000000000.',hints:['Un prefijo anterior debe valer prefijoActual−K.', 'Consulta antes de registrar el prefijo actual.'],solution:'Para cada extremo derecho contamos exactamente sus inicios válidos mediante frecuencias de prefijos anteriores. Cada subarreglo tiene un único extremo derecho, por lo que no se duplica. El código usa unordered_map con O(n) esperado y O(n) memoria; cambiarlo por map da O(n log n) garantizado. Prefijos y respuesta se guardan en 64 bits.',code:"#include <iostream>\n#include <unordered_map>\nusing namespace std;\nint main() {\n    int n;\n    long long k;\n    cin >> n >> k;\n    unordered_map<long long, long long> f;\n    f.reserve(2 * n + 1);\n    f[0] = 1;\n    long long p = 0, ans = 0;\n    for (int i = 0; i < n; i++) {\n        long long x;\n        cin >> x;\n        p += x;\n        auto it = f.find(p - k);\n        if (it != f.end())\n            ans += it->second;\n        f[p]++;\n    }\n    cout << ans << \"\\n\";\n}",tests:[{input:'3 1\n1 -1 1\n',output:'3\n'},{input:'3 0\n0 0 0\n',output:'6\n'},{input:'1 2\n-2\n',output:'0\n'}]});

add('meet-in-the-middle',[
 {title:'Partir las decisiones, no el objetivo',body:'Para contar subconjuntos de n números que suman T, la enumeración completa tiene 2 elevado a n posibilidades. Si n=40, eso supera un billón. Divide los elementos en dos mitades de 20 y enumera por separado sus sumas, aproximadamente un millón por lado. Cada subconjunto total corresponde a una pareja única: su parte izquierda y su parte derecha. La meta sigue siendo T, pero para cada suma izquierda x buscamos sumas derechas T−x. Esa correspondencia es la prueba de que la combinación no pierde información.'},
 {title:'Generar todas las sumas sin un ciclo por máscara',body:'Empieza con la lista [0], que representa el subconjunto vacío. Para cada elemento a, guarda el tamaño actual y agrega una copia de cada suma existente más a. Si los elementos son [2,5], las listas pasan por [0], [0,2], [0,2,5,7]. Es importante recorrer solo el tamaño anterior: si recorres también lo recién insertado, reutilizarías a indefinidamente. Las sumas repetidas deben conservarse cuando contamos subconjuntos distintos por sus índices, incluso si algunos valores son iguales.'},
 {title:'Combinar con búsquedas y controlar repetidos',body:'Ordena las sumas derechas. Para cada x de la izquierda, equal_range(T−x) devuelve el bloque de coincidencias; su longitud es cuántos subconjuntos derechos completan ese x. Para [1,1,2] y T=2, hay dos subconjuntos: los dos unos y el elemento 2. Si T=0 y hay ceros, el vacío y los subconjuntos de ceros también cuentan en este ejercicio. No elimines duplicados con unique: perderías multiplicidades y cambiarías la pregunta de contar a preguntar existencia.'},
 {title:'Costo real y variantes',body:'Generar las mitades cuesta O(2^(n/2)); ordenar y consultar agrega un factor O(n), de modo que una cota es O(n·2^(n/2)). La memoria también es exponencial: dos millones de long long ocupan alrededor de 16 MB más capacidad adicional de vectores. Para n=50, las listas ya crecen a decenas de millones. La técnica también permite maximizar una suma a lo sumo T con upper_bound o contar pares dentro de un rango. Si los números son pequeños y su suma total acotada, una DP por suma puede ser mucho mejor.'},
],{title:'Conservar las multiplicidades',prompt:'Para [0,1,1] y objetivo 1, enumera los subconjuntos válidos por índices 0,1,2. ¿Por qué hay más soluciones que valores distintos? Explica qué ocurriría si eliminas sumas repetidas de las mitades.',hints:['El cero se puede incluir o excluir sin cambiar la suma.', 'Los dos unos están en posiciones diferentes.'],solution:'Los subconjuntos son {1},{2},{0,1},{0,2}: cuatro. Aunque todos suman 1, representan elecciones distintas de índices. Eliminar sumas repetidas borraría parte de esa información y subcontaría. Si el objetivo fuese solo decidir existencia, los repetidos podrían descartarse; para contar, deben conservarse o almacenarse con frecuencia. El enunciado define cuándo dos resultados son distintos.'},{title:'Selecciones con suma exacta',prompt:'Lee n,T y n enteros. Cuenta los subconjuntos de índices cuya suma sea T; incluye el subconjunto vacío. Límites: 0 ≤ n ≤ 40; |a[i]| ≤ 1000000000; |T| ≤ 40000000000. Imprime el conteo exacto.',hints:['Enumera sumas de cada mitad incluyendo cero.', 'Por cada suma izquierda cuenta todas las coincidencias derechas.'],solution:'La descomposición de un subconjunto en sus dos mitades es única. Contar coincidencias T−x para cada suma x suma exactamente todas las parejas válidas, incluyendo multiplicidades. Ordenamos la mitad derecha y usamos equal_range. El costo es O(n·2^(n/2)) y memoria O(2^(n/2)); long long soporta tanto sumas como hasta 2^40 subconjuntos.',tests:[{input:'3 1\n0 1 1\n',output:'4\n'},{input:'0 0\n',output:'1\n'},{input:'4 0\n1 -1 2 -2\n',output:'4\n'}]});

add('gold-conclusion',[
 {title:'Del enunciado a una recurrencia en un DAG',body:'Una competencia final de Oro debe exigir modelar, no reconocer una palabra. Considera sedes conectadas por rutas dirigidas sin ciclos, cada una con un tiempo de viaje no negativo. Quieres el tiempo máximo de una ruta desde la sede 0 hasta la n−1. La ausencia de ciclos permite un orden topológico; maximizar caminos en un grafo general sería un problema muy diferente. Define dp[v] como la mayor duración de una ruta válida desde 0 hasta v, o imposible si no existe. Esta definición separa una distancia cero válida de un vértice inalcanzable.'},
 {title:'Combinar orden y transición',body:'Inicializa dp[0]=0 y los demás en menos infinito. Al procesar u en orden topológico, para cada arista u→v de peso w propone dp[u]+w si u es alcanzable. Guarda el máximo. Todos los predecesores se procesan antes de v, por lo que dp[v] ya contiene todas sus rutas posibles cuando lo uses para continuar. La demostración divide rutas por su última arista: todo candidato válido aparece y ninguna transición inventa una ruta. El orden topológico es la infraestructura que hace válida esa inducción.'},
 {title:'Una traza con caminos alternativos',body:'En 0→1 de peso 3,0→2 de peso 5,1→3 de peso 8,2→3 de peso 2, las rutas completas cuestan 11 y 7. dp empieza [0,imposible,imposible,imposible]; después de 0 queda [0,3,5,imposible]; procesar 1 propone 11 para 3 y procesar 2 propone 7, que no mejora. El resultado es 11. Una BFS encontraría cantidad mínima de aristas; Dijkstra minimizaría pesos. Ninguno coincide con maximizar duración en un DAG, aunque todos usen las mismas conexiones.'},
 {title:'Una auditoría antes de pasar al siguiente nivel',body:'Comprueba el modelo, los casos base, cada transición, el orden de evaluación y el costo. Pregunta qué cambia con aristas negativas, con ciclos o con múltiples orígenes. En el DAG los pesos negativos no rompen la DP, pero inicializar imposibles en cero sí puede inventar rutas. Un ciclo impide el orden y puede permitir duración ilimitada si se repite con peso positivo. El costo de Kahn más DP es O(n+m), memoria O(n+m). Para entrenar por tu cuenta, primero resuelve casos diminutos a mano, luego compara el programa y por último explica por qué los límites grandes siguen siendo seguros.'},
],{title:'Escoger la técnica por el objetivo',prompt:'En el DAG 0→1 de peso 6,0→2 de peso 2,2→1 de peso 1,1→3 de peso 4, calcula la ruta mínima y la máxima desde 0 a 3. ¿Por qué el mismo orden topológico puede servir para ambas pero la transición cambia?',hints:['Las rutas tienen costos 10 y 7.', 'La operación de combinación representa lo que deseas optimizar.'],solution:'La mínima usa 0→2→1→3 y cuesta 7; la máxima usa 0→1→3 y cuesta 10. El orden [0,2,1,3] respeta todas las dependencias. Para mínimo combinas con min e infinito para imposibles; para máximo, max y menos infinito. El orden resuelve cuándo evaluar; el significado de dp y la operación resuelven qué se está calculando. Copiar una tabla sin definir ese significado puede resolver el objetivo contrario.'},{title:'Recorrido de mayor duración',prompt:'Lee n,m y m aristas dirigidas u v w entre vértices de 0 a n−1. Si el grafo tiene algún ciclo, imprime CICLO. Si es un DAG, imprime la máxima suma de pesos de una ruta de 0 a n−1, o IMPOSIBLE si no existe. Límites: 1 ≤ n ≤ 200000; 0 ≤ m ≤ 300000; 0 ≤ w ≤ 1000000000. La ruta vacía de 0 a sí mismo tiene costo cero.',hints:['Obtén orden topológico y verifica que incluya todos los vértices.', 'Propaga máximos solo desde estados alcanzables.'],solution:'Kahn detecta ciclos y produce un orden de dependencias. En un DAG, cada ruta a v termina en una arista desde un predecesor ya resuelto; tomar el máximo de esas extensiones calcula el óptimo por inducción. Un centinela −1 basta para inalcanzables porque los pesos son no negativos. Tiempo y memoria O(n+m); costos en long long.',code:"#include <iostream>\n#include <vector>\n#include <queue>\n#include <algorithm>\nusing namespace std;\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<pair<int, long long>>> g(n);\n    vector<int> in(n);\n    while (m--) {\n        int a, b;\n        long long w;\n        cin >> a >> b >> w;\n        g[a].push_back({b, w});\n        in[b]++;\n    }\n    queue<int> q;\n    for (int i = 0; i < n; i++)\n        if (in[i] == 0)\n            q.push(i);\n    vector<int> o;\n    while (!q.empty()) {\n        int v = q.front();\n        q.pop();\n        o.push_back(v);\n        for (auto [u, w] : g[v])\n            if (--in[u] == 0)\n                q.push(u);\n    }\n    if ((int)o.size() != n) {\n        cout << \"CICLO\\n\";\n        return 0;\n    }\n    vector<long long> d(n, -1);\n    d[0] = 0;\n    for (int v : o)\n        if (d[v] != -1)\n            for (auto [u, w] : g[v])\n                d[u] = max(d[u], d[v] + w);\n    if (d[n - 1] == -1)\n        cout << \"IMPOSIBLE\\n\";\n    else\n        cout << d[n - 1] << \"\\n\";\n}",tests:[{input:'4 4\n0 1 3\n0 2 5\n1 3 8\n2 3 2\n',output:'11\n'},{input:'2 0\n',output:'IMPOSIBLE\n'},{input:'2 2\n0 1 1\n1 0 1\n',output:'CICLO\n'},{input:'1 0\n',output:'0\n'}]});
